/* ===== SEASONAL CALC MODEL (эталон Katabello, RATE $1=35฿) ===== */
var RATE=35;
function mkCalc(priceUSD,areaM2){
  var priceTHB=Math.round(priceUSD*RATE);
  var f=priceTHB/8401000;
  return {
    priceTHB:priceTHB,
    handoverTHB:Math.round(priceTHB*1.35),
    areaM2:areaM2,mgmtPct:20,maintM2Month:80,capexM2:800,metersTHB:15000,capGrowthPct:3,buildYears:1,
    seasons:{
      high:{rent:Math.round(156250*f),occ:90,months:4},
      shoulder:{rent:Math.round(115000*f),occ:87.6,months:2},
      low:{rent:Math.round(60000*f),occ:73,months:6}
    }
  };
}
var CALC_DEFAULTS=mkCalc(240000,66);



