/* ===== LANG STATE ===== */
/* 21.09: язык страницы теперь может задать сама страница — английские копии в
   /en/ ставят window.__PL_LANG. Полагаться только на localStorage нельзя:
   посетитель приходит на английский адрес из поиска с пустым хранилищем, и
   витрина перерисовывала всё обратно по-русски. Выбор человека (кнопка RU/EN)
   по-прежнему главнее: он и пишется в localStorage. */
PL.lang=(function(){
  try{ var v=localStorage.getItem('pl_lang'); if(v==='ru'||v==='en') return v; }catch(e){}
  try{ if(window.__PL_LANG==='en'||window.__PL_LANG==='ru') return window.__PL_LANG; }catch(e){}
  return 'ru';
})();
document.addEventListener('DOMContentLoaded',function(){ try{ setCur(PL.cur); }catch(e){} });
function t(k){var d=PL.I18N[PL.lang]||PL.I18N.ru;return d[k]!=null?d[k]:(PL.I18N.ru[k]!=null?PL.I18N.ru[k]:k);}
function loc(o){return (o&&(o[PL.lang]||o.ru))||'';}

/* Название объекта приходит из базы по-русски: «AYANA Heights · квартира (U3)»,
   «Villa Estella · вилла, 3 спальни». Английского имени в данных нет, и заводить
   второе поле ради двух служебных слов незачем: в CRM и офферах имя должно
   остаться прежним. На английской версии переводим только эти слова. */
/* Границу слова \b в JavaScript с кириллицей использовать нельзя: для движка
   русская буква не «словесный символ», и /квартира\b/ не совпадает ни с чем.
   Эта грабля у нас уже была записана, и я в неё всё равно наступил — первые
   правила молча не срабатывали. Вместо \b проверяем, что дальше не буква. */
var НЕБУКВА='(?![А-Яа-яЁёA-Za-z])';
var СЛУЖЕБНЫЕ=[
  [/·\s*квартира\s*\(/g,'· apartment ('], [/·\s*вилла,\s*/g,'· villa, '],
  [/·\s*вилла\s*\(/g,'· villa ('],
  [new RegExp('·\\s*квартира'+НЕБУКВА,'g'),'· apartment'],
  [new RegExp('·\\s*вилла'+НЕБУКВА,'g'),'· villa'],
  [new RegExp('(\\d+)\\s*спальни'+НЕБУКВА,'g'),'$1 bedrooms'],
  [new RegExp('(\\d+)\\s*спальня'+НЕБУКВА,'g'),'$1 bedroom'],
  [new RegExp('(\\d+)\\s*спален'+НЕБУКВА,'g'),'$1 bedrooms'],
  [new RegExp(',\\s*Таланг'+НЕБУКВА,'g'),', Thalang'],
  [new RegExp(',\\s*Пхукет'+НЕБУКВА,'g'),', Phuket'],
];
function titleOf(p){
  var t=(p&&p.title)||'';
  if(PL.lang!=='en') return t;
  for(var i=0;i<СЛУЖЕБНЫЕ.length;i++) t=t.replace(СЛУЖЕБНЫЕ[i][0],СЛУЖЕБНЫЕ[i][1]);
  return t;
}

function applyI18n(){
  document.querySelectorAll('[data-i18n]').forEach(function(el){el.innerHTML=t(el.getAttribute('data-i18n'));});
  document.querySelectorAll('[data-i18n-ph]').forEach(function(el){el.placeholder=t(el.getAttribute('data-i18n-ph'));});
  document.querySelectorAll('[data-i18n-title]').forEach(function(el){var v=t(el.getAttribute('data-i18n-title'));el.setAttribute('title',v);el.setAttribute('aria-label',v);});
  document.documentElement.lang=PL.lang;
  document.title=t('meta.title');
  var md=document.querySelector('meta[name="description"]');if(md)md.setAttribute('content',t('meta.desc'));
  document.querySelectorAll('[data-l]').forEach(function(b){b.classList.toggle('on',b.dataset.l===PL.lang);});
  /* re-measure open FAQ answers after texts changed */
  document.querySelectorAll('.faq-item.open .faq-a').forEach(function(a){a.style.maxHeight=a.scrollHeight+'px';});
}
function setLang(l){
  if(PL.lang===l)return;
  PL.lang=l;try{localStorage.setItem('pl_lang',l);}catch(e){}
  applyI18n();renderSale();renderRent();renderMap();renderDList();renderMapReal();
  if(document.getElementById('propModal').classList.contains('open')&&currentPid){openProp(currentPid);}
  if(document.getElementById('quizModal').classList.contains('open'))renderQuiz();
  updateTray();
}

/* ===== LIQUID BG (жидкий силикон, одна палитра; не критичен — в try/catch) ===== */
var reduceMotion=false;
try{reduceMotion=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);}catch(e){}
try{
  var cv=document.getElementById('liquid'),cxx=cv.getContext('2d');
  if(!cxx)throw new Error('no canvas 2d');
  var W,H,blobs=[],raf=null,scY=0;
  var PALETTE=['#d2d5b3','#cbc7bd','#e4e6cc','#b9c08f','#e8e2cf','#d8d6cb'];
  var resize=function(){W=cv.width=innerWidth*1.2;H=cv.height=innerHeight*1.2;};
  var makeBlobs=function(){blobs=[];for(var i=0;i<6;i++){blobs.push({x:Math.random()*W,y:Math.random()*H,r:200+Math.random()*220,c:PALETTE[i%PALETTE.length],vx:(Math.random()-.5)*.3,vy:(Math.random()-.5)*.3,px:Math.random()*6.28});}};
  var drawStatic=function(){cxx.clearRect(0,0,W,H);blobs.forEach(function(b){var g=cxx.createRadialGradient(b.x,b.y,0,b.x,b.y,b.r);g.addColorStop(0,b.c);g.addColorStop(1,b.c+'00');cxx.fillStyle=g;cxx.beginPath();cxx.arc(b.x,b.y,b.r,0,6.2832);cxx.fill();});};
  var draw=function(tm){
    cxx.clearRect(0,0,W,H);
    for(var i=0;i<blobs.length;i++){var b=blobs[i];
      b.x+=b.vx;b.y+=b.vy;b.x+=Math.sin(tm/3000+b.px)*0.4;b.y+=Math.cos(tm/3400+b.px)*0.4;
      if(b.x<-300)b.x=W+200;if(b.x>W+300)b.x=-200;if(b.y<-300)b.y=H+200;if(b.y>H+300)b.y=-200;
      var yy=b.y-scY*0.06;
      var g=cxx.createRadialGradient(b.x,yy,0,b.x,yy,b.r);g.addColorStop(0,b.c);g.addColorStop(1,b.c+'00');
      cxx.fillStyle=g;cxx.beginPath();cxx.arc(b.x,yy,b.r,0,6.2832);cxx.fill();
    }
    raf=requestAnimationFrame(draw);
  };
  addEventListener('resize',function(){resize();makeBlobs();if(reduceMotion)drawStatic();});
  addEventListener('scroll',function(){scY=window.scrollY||document.documentElement.scrollTop;},{passive:true});
  resize();makeBlobs();
  if(reduceMotion){drawStatic();}else{raf=requestAnimationFrame(draw);}
}catch(e){/* фон не критичен: без canvas страница живёт */}

/* ===== REVEAL ON SCROLL ===== */
var io=null;
if('IntersectionObserver' in window){
  /* threshold:.1 требовал показать 10% ПЛОЩАДИ блока. Каталог высотой ~14700px
     столько не покажет никогда — 10% это 1470px при экране 844px, — и весь
     список объектов навсегда оставался прозрачным: «пустой экран» на buy.html.
     Считаем по факту входа в вид, а не по доле площади. */
  io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}});},{threshold:0,rootMargin:'0px 0px -8% 0px'});
}
function observeReveals(){
  document.querySelectorAll('.reveal:not(.visible)').forEach(function(el){
    if(io)io.observe(el);else el.classList.add('visible');
  });
}
/* Страховка: контент не должен зависеть от анимации. Если через 2 секунды
   блок в поле зрения всё ещё прозрачен — показываем его без анимации. */
setTimeout(function(){
  document.querySelectorAll('.reveal:not(.visible)').forEach(function(el){
    var r=el.getBoundingClientRect();
    if(r.top < innerHeight && r.bottom > 0) el.classList.add('visible');
  });
},2000);

