function closeChatToProp(pid){closeChat();openProp(pid);}
function clearChat(){chatHist=[];leadShown=false;chatStarted=false;userMsgs=0;lastTopic=null;lastLeadSummary=null;saveHist();cb.innerHTML='';openChat('reset');}
/* Голосовой ввод в чате (Эльнур 06.09). Распознаёт сам браузер — запись
   никуда не отправляется. Где не поддерживается (Firefox) — кнопки просто нет. */
var CHAT_REC=null;
/* ===== ОБМЕН ГОЛОСОВЫМИ =====
   Эльнур 08.09: «я хотел общение в режиме диалога, чтобы ИИ чат мог отправить
   голосовое сообщение, и клиент тоже мог отправить голосовое, а не текст под
   диктовку». Поэтому: нажал — записалось, в переписке появилось ваше голосовое,
   которое можно переслушать; ответ приходит тоже голосовым, а текст под ним —
   чтобы можно было прочитать. */
function vmSecs(n){ n=Math.max(0,Math.round(n||0)); return Math.floor(n/60)+':'+('0'+(n%60)).slice(-2); }
/* пузырь с голосовым: играет из своего источника, показывает дорожку и время */
function voiceBubble(kind, play, dur, text){
  var d=document.createElement('div'); d.className='msg '+kind;
  var w=document.createElement('div'); w.className='vm';
  var b=document.createElement('button'); b.type='button'; b.className='vm-play'; b.textContent='▶';
  var wave=document.createElement('span'); wave.className='vm-wave';
  var fill=document.createElement('i'); wave.appendChild(fill);
  var tm=document.createElement('span'); tm.className='vm-time'; tm.textContent=vmSecs(dur);
  w.appendChild(b); w.appendChild(wave); w.appendChild(tm);
  d.appendChild(w);
  if(text){ var tx=document.createElement('div'); tx.className='vm-text'; tx.textContent=text; d.appendChild(tx); }
  cb.appendChild(d); cb.scrollTop=cb.scrollHeight;
  var ctl=null;
  b.onclick=function(){
    if(ctl && ctl.stop){ ctl.stop(); ctl=null; b.textContent='▶'; fill.style.width='0'; return; }
    b.textContent='⏸';
    ctl=play({
      progress:function(p){ fill.style.width=Math.round(Math.min(1,p)*100)+'%'; },
      time:function(sec){ tm.textContent=vmSecs(sec); },
      done:function(){ b.textContent='▶'; fill.style.width='0'; ctl=null; }
    });
  };
  return { el:d, start:function(){ b.onclick(); } };
}
/* проигрывание записанного файла */
function playAudio(url){
  return function(cbs){
    var a=new Audio(url);
    a.ontimeupdate=function(){ if(a.duration) cbs.progress(a.currentTime/a.duration); cbs.time(a.currentTime); };
    a.onended=function(){ cbs.done(); };
    a.play();
    return { stop:function(){ try{ a.pause(); }catch(e){} } };
  };
}
/* проигрывание ответа голосом самого браузера */
function playSpeech(text){
  return function(cbs){
    if(!window.speechSynthesis){ cbs.done(); return null; }
    try{ speechSynthesis.cancel(); }catch(e){}
    var u=new SpeechSynthesisUtterance(text);
    u.lang=(PL.lang==='en')?'en-US':'ru-RU'; u.rate=1.02;
    var vs=speechSynthesis.getVoices()||[];
    var v=vs.filter(function(x){ return x.lang && x.lang.indexOf(u.lang.slice(0,2))===0; })[0];
    if(v) u.voice=v;
    var t0=Date.now(), total=Math.max(2, text.length/14);
    var tick=setInterval(function(){
      var el=(Date.now()-t0)/1000;
      cbs.progress(el/total); cbs.time(el);
    }, 200);
    u.onend=function(){ clearInterval(tick); cbs.done(); };
    u.onerror=function(){ clearInterval(tick); cbs.done(); };
    speechSynthesis.speak(u);
    return { stop:function(){ clearInterval(tick); try{ speechSynthesis.cancel(); }catch(e){} } };
  };
}
/* ответ голосом: пузырь играет сам, текст читаемый под ним */
function botVoice(text){
  var v=voiceBubble('bot', playSpeech(text), Math.max(2, text.length/14), text);
  chatHist.push({r:'bot',h:escHtml(text)}); saveHist();
  setTimeout(function(){ try{ v.start(); }catch(e){} }, 200);
  return v;
}
/* Режим «Общаемся голосом»: ответы приходят голосовыми. Помним выбор. */
/* Эльнур 08.09: «функция голосовые так себе, голос корявый, можно оставить
   как и было — обычный ИИ-чат без голоса». Голос выключен: браузерный голос
   звучит неживо, а серверный упирается в кредиты. Код оставлен на случай,
   если решим вернуться, но в интерфейсе его нет. */
var VOICE_MODE=false;
function paintVoiceMode(){
  var b=document.getElementById('chatVmode'); if(!b) return;
  b.classList.toggle('on', VOICE_MODE);
  b.textContent = VOICE_MODE ? 'Голосом ✓' : 'Голосом';
}
function toggleVoiceMode(){
  VOICE_MODE=!VOICE_MODE;
  try{ localStorage.setItem('plp_voice_mode', VOICE_MODE?'1':'0'); }catch(e){}
  paintVoiceMode();
  bot(VOICE_MODE
    ? 'Хорошо, отвечаю голосом. Нажмите микрофон и говорите — я расшифрую и отвечу голосовым. Выключить можно той же кнопкой.'
    : 'Вернулась к тексту. Голосовое всё равно можно отправить — нажмите микрофон.');
}
/* Строка «слушаю»: видно, что запись идёт, сколько секунд и что уже разобрали.
   Эльнур 08.09: «не видно, что идёт запись, не понятно, что записал голос, что нет». */
function listenBar(){
  var d=document.createElement('div'); d.className='vlisten';
  var dot=document.createElement('span'); dot.className='vd';
  var tm=document.createElement('span'); tm.className='vt'; tm.textContent='0:00';
  var tx=document.createElement('span'); tx.className='vx'; tx.textContent='Слушаю — говорите, нажмите ещё раз, когда закончите';
  d.appendChild(dot); d.appendChild(tm); d.appendChild(tx);
  cb.appendChild(d); cb.scrollTop=cb.scrollHeight;
  var t0=Date.now();
  var iv=setInterval(function(){
    var n=Math.round((Date.now()-t0)/1000);
    tm.textContent=Math.floor(n/60)+':'+('0'+(n%60)).slice(-2);
  },250);
  return { el:d, secs:function(){ return (Date.now()-t0)/1000; },
           heard:function(t){ tx.textContent = t ? t : 'Слушаю…'; cb.scrollTop=cb.scrollHeight; },
           close:function(){ clearInterval(iv); d.remove(); } };
}
function chatVoice(){
  var btn=document.getElementById('chatMic');
  /* второе нажатие — закончить */
  if(window.__sr){ try{ window.__sr.stop(); }catch(e){} return; }
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){
    /* Честно и сразу, а не после записи в пустоту: серверная расшифровка сейчас
       недоступна, поэтому распознаёт только сам браузер. */
    bot('Этот браузер не распознаёт речь. В Chrome на компьютере и Android голосовые работают, '+
        'а здесь — напишите, пожалуйста, текстом.');
    return;
  }
  var r=new SR();
  r.lang=(PL.lang==='en')?'en-US':'ru-RU';
  r.interimResults=true; r.continuous=true;
  var heard='', partial='', bar=null, stopped=false;
  r.onstart=function(){
    window.__sr=r;
    if(btn){
      btn.classList.add('rec'); btn.setAttribute('aria-label','Закончить запись');
      /* Состояние записи задаём прямо на кнопке: так его не перебьёт ни одно
         правило стилей. Эльнур 08.09: «не видно, что идёт запись». */
      btn.style.setProperty('background','var(--green)','important');
      btn.style.setProperty('color','var(--on-green,#14150F)','important');
      btn.style.setProperty('border-color','transparent','important');
    }
    bar=listenBar();
  };
  r.onresult=function(e){
    partial='';
    for(var i=e.resultIndex;i<e.results.length;i++){
      var t=e.results[i][0].transcript;
      if(e.results[i].isFinal) heard+=t; else partial+=t;
    }
    if(bar) bar.heard((heard+partial).trim());
  };
  r.onerror=function(ev){
    stopped=true;
    if(bar) bar.close();
    if(btn){ btn.classList.remove('rec');
      btn.style.removeProperty('background'); btn.style.removeProperty('color');
      btn.style.removeProperty('border-color'); }
    window.__sr=null;
    var why=(ev&&ev.error)||'';
    bot(why==='not-allowed'
      ? 'Не дали доступ к микрофону. Разрешите его в браузере и нажмите ещё раз.'
      : (why==='no-speech'
         ? 'Ничего не услышала. Нажмите микрофон и говорите — или напишите текстом.'
         : 'Не получилось записать голос. Напишите, пожалуйста, текстом.'));
  };
  r.onend=function(){
    window.__sr=null;
    if(btn){
      btn.classList.remove('rec'); btn.setAttribute('aria-label','Сказать голосом');
      btn.style.removeProperty('background'); btn.style.removeProperty('color');
      btn.style.removeProperty('border-color');
    }
    if(stopped) return;
    var secs=bar?bar.secs():0;
    if(bar) bar.close();
    var text=(heard+' '+partial).replace(/\s+/g,' ').trim();
    if(!text){
      bot('Не разобрала голос. Нажмите микрофон и скажите ещё раз — или напишите текстом.');
      return;
    }
    /* Ваше голосовое в переписке: слышно, что записалось, и написано, что разобрали. */
    voiceBubble('me', playSpeech(text), Math.max(1, secs), text);
    chatHist.push({r:'me',h:text}); saveHist();
    userMsgs++;
    askAI(text, true);
  };
  try{ r.start(); }
  catch(e){ window.__sr=null; bot('Микрофон занят другой вкладкой. Закройте её и попробуйте снова.'); }
}
/* Озвучка ответа. Сначала пробуем голос самого браузера — он есть почти везде
   и ничего не стоит. Если браузер не умеет, просим сервер собрать аудио. */
function speak(btn, text){
  if(!text) return;
  try{
    if(window.speechSynthesis){
      if(speechSynthesis.speaking){ speechSynthesis.cancel(); btn.textContent='🔊'; return; }
      var u=new SpeechSynthesisUtterance(text);
      u.lang=(typeof LANG!=='undefined'&&LANG==='en')?'en-US':'ru-RU';
      u.rate=1.02; u.pitch=1.0;
      var vs=speechSynthesis.getVoices()||[];
      var v=vs.filter(function(x){ return x.lang && x.lang.indexOf(u.lang.slice(0,2))===0; })[0];
      if(v) u.voice=v;
      btn.textContent='⏸';
      u.onend=function(){ btn.textContent='🔊'; };
      u.onerror=function(){ btn.textContent='🔊'; };
      speechSynthesis.speak(u);
      return;
    }
  }catch(e){}
  btn.disabled=true; var was=btn.textContent; btn.textContent='…';
  fetch(VOICE_ENDPOINT,{method:'POST',headers:{'Content-Type':'text/plain'},
        body:JSON.stringify({action:'tts',text:text})})
    .then(function(r){return r.json();})
    .then(function(d){
      btn.disabled=false; btn.textContent=was;
      if(d&&d.ok&&d.audio){ new Audio(d.audio).play(); }
    })
    .catch(function(){ btn.disabled=false; btn.textContent=was; });
}

