function isObjectHash(){return /^#(object=|\/object\/)/.test(location.hash||'');}
function setObjectHash(pid){
  try{history.replaceState(null,'','#object='+encodeURIComponent(pid));}catch(e){}
}
function clearObjectHash(){
  if(!isObjectHash())return; /* не трогаем чужие якоря (#faq и т.п.) */
  try{history.replaceState(null,'',location.pathname+location.search);}catch(e){location.hash='';}
}
function shareUrl(pid){
  /* чистый URL отдельной страницы объекта (лучше для клиента и SEO): object/<slug>.html
     slug из property_id: PLP-HERITAGE → heritage. База = каталог без index.html. */
  var slug=String(pid).replace(/^PLP-/,'').toLowerCase();
  var base=location.pathname.replace(/[^/]*$/,''); /* .../plp-site/ */
  /* 17.09 Эльнур: «и никаких хтмл в адресах вообще» — делимся чистым адресом,
     тем же, что показывает адресная строка самой страницы объекта. */
  return location.origin+base+'object/'+slug;
}
function showToast(msg){
  var el=document.getElementById('plToast');if(!el)return;
  el.textContent=msg;el.classList.add('show');
  clearTimeout(el.__t);el.__t=setTimeout(function(){el.classList.remove('show');},2400);
}
function shareProp(){
  if(!currentPid)return;
  var url=shareUrl(currentPid);
  function ok(){showToast(t('u.copied'));}
  function fail(){
    /* запасной путь: временный textarea + execCommand */
    try{
      var ta=document.createElement('textarea');ta.value=url;ta.setAttribute('readonly','');
      ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);
      ta.select();var done=document.execCommand('copy');document.body.removeChild(ta);
      if(done)ok();else showToast(t('u.copyfail'));
    }catch(e){showToast(t('u.copyfail'));}
  }
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(url).then(ok).catch(fail);
  }else{fail();}
}
function openFromHash(){
  var h=location.hash||'';var m=h.match(/^#(?:object=|\/object\/)([A-Za-z0-9_\-]+)/);
  if(!m)return;
  var pid=decodeURIComponent(m[1]);
  var p=PL.byId[pid];
  var ask=/[?&]ask=1/.test(h);
  /* 🔴 17.09 Эльнур: «нажал „задать вопрос по объекту“ — просто перешёл на другую
     версию отображения этого проекта, новой страницы, непонятно, зачем оно».
     Со страницы объекта человек уже всё про него прочитал: показывать ему ту же
     карточку вторым способом незачем. По «задать вопрос» открываем только чат. */
  var wantCalc=/[?&]calc=1/.test(h);
  if(p&&!p.soon&&!ask)openProp(pid); /* openProp сам валидирует id */
  /* «Рассчитать доходность» со страницы объекта: калькулятор живёт в карточке,
     поэтому открываем её сразу на калькуляторе, а не заставляем его искать. */
  if(p&&wantCalc)setTimeout(function(){
    try{
      var d=document.querySelector('#pmTool .calc-more'); if(!d) return;
      d.open=true; d.scrollIntoView({behavior:'smooth',block:'start'});
    }catch(e){}
  },350);
  if(p&&ask){
    pendingIntent={funnel:(/аренда|rent/i.test(p.purpose||'')?'rent':'sale'),
                   property_id:pid,goal:'question',note:'Вопрос по объекту: '+(p.title||pid)};
    setTimeout(function(){ try{ openChat('object'); }catch(e){} },500);
  }
}
function closeProp(){document.getElementById('propModal').classList.remove('open');document.body.style.overflow='';currentPid=null;clearObjectHash();}
/* WhatsApp с контекстом. Эльнур 04.09: «вызов на ватсап не плохо, просто это
   надо сделать логично, последовательно». Решение как у Malina: на холодных
   местах (шапка, первый экран) — подбор и чат, а WhatsApp появляется там, где
   контекст уже есть — в карточке объекта и в конце квиза. Человек попадает
   в переписку с готовым сообщением: объект, цена, даты, ссылка. Менеджеру
   не нужно ничего переспрашивать. */
function waLink(p, extra){
  var lines=[];
  if(p){
    lines.push(t('wa.hi')+' '+p.title+(p.loc?(' · '+loc(p.loc)):''));
    if(p.funnel==='sale') lines.push(t('wa.price')+' '+fmtBaht(thbOf(p)));
    var d=(typeof rentSelDates!=='undefined'&&rentSelDates)?rentSelDates:null;
    if(p.funnel==='rent'&&d&&d.from&&d.to) lines.push(t('wa.dates')+' '+d.from+' — '+d.to);
    lines.push(t('wa.link')+' '+location.origin+location.pathname+'#object='+encodeURIComponent(p.property_id));
  }else{
    lines.push(t('wa.hi2'));
    var v=viewedList().slice(0,3);
    if(v.length) lines.push(t('wa.seen')+' '+v.map(function(x){return x.title;}).join(', '));
  }
  if(extra) lines.push(extra);
  return 'https://wa.me/66955492587?text='+encodeURIComponent(lines.join('\n'));
}
function waFromModal(pid){
  var p=PL.byId[pid]; if(!p) return;
  /* заявку фиксируем у себя до перехода: иначе переписка начнётся мимо CRM */
  try{ pushLead({funnel:p.funnel,property_id:pid,goal:'whatsapp',channel:'whatsapp'}); }catch(e){}
  window.open(waLink(p),'_blank','noopener');
}
function leadFromModal(pid,kind){var p=PL.byId[pid];closeProp();pushLead({funnel:p.funnel,property_id:pid,goal:kind});openChat('object');setTimeout(function(){offerLead(true);},600);}
/* блок «включено / не включено / правила» для карточки аренды (значения из БД, RU-текст) */
function rentDetailsHTML(p){
  var rows='';
  if(p.included)rows+='<div class="rd-row"><b>✓ '+t('rent.d.incl')+'</b><span>'+escHtml(p.included)+'</span></div>';
  if(p.excluded)rows+='<div class="rd-row"><b>— '+t('rent.d.excl')+'</b><span>'+escHtml(p.excluded)+'</span></div>';
  if(p.rules)rows+='<div class="rd-row"><b>ⓘ '+t('rent.d.rules')+'</b><span>'+escHtml(p.rules)+'</span></div>';
  if(!rows)return '';
  return '<div class="rentdetails">'+rows+'</div>';
}
/* Расчёт проживания по датам: сетку цен и скидки за срок считает база. */
function wireStay(p){
  var a=document.getElementById('stayIn'), b=document.getElementById('stayOut'),
      box=document.getElementById('stayOutBox');
  if(!a||!b||!box) return;
  if(rentSelDates&&rentSelDates.check_in){ a.value=rentSelDates.check_in; b.value=rentSelDates.check_out||''; }
  mkRangeField({inId:'stayIn',outId:'stayOut',btnId:'stayRangeBtn',
                calId:'stayRangeCal',labelId:'stayRangeT'});
  function ask(){
    if(!a.value||!b.value||b.value<=a.value){ box.innerHTML=''; return; }
    box.innerHTML='<span class="stay-wait">'+t('stay.wait')+'</span>';
    fetch('https://api.property-library.com/ukowner',{method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({action:'stay_quote',property_id:p.property_id,from:a.value,to:b.value})})
      .then(function(r){return r.json();})
      .then(function(d){
        if(!d||!d.ok){
          /* сетки по объекту ещё нет — честно говорим и ведём к менеджеру */
          box.innerHTML='<div class="stay-none">'+t('stay.none')+'</div>';
          return;
        }
        rentSelDates={check_in:a.value,check_out:b.value,from:a.value,to:b.value};
        box.innerHTML=
          '<div class="stay-sum"><b>'+fmtBaht(d.total)+'</b>'+
          '<span>'+d.nights+' '+t('stay.nights')+' · '+fmtBaht(d.avg_night)+t('stay.pernight')+'</span></div>'+
          (d.discount_pct>0?('<div class="stay-off">−'+d.discount_pct+'% '+t('stay.off')+
             ' <s>'+fmtBaht(d.gross)+'</s></div>'):'');
      })
      .catch(function(){ box.innerHTML='<div class="stay-none">'+t('stay.none')+'</div>'; });
  }
  a.onchange=b.onchange=ask;
  if(a.value&&b.value) ask();
}
function wireBooking(p){
  try{ wireStay(p); }catch(e){}
  var req=document.getElementById('bReq');if(!req)return;
  /* 🔴 17.09 Эльнур: «а самое интересное — как там отправить запрос на аренду то?».
     Кнопка отправляла намерение и уводила в чат, а заявка без контакта до менеджера
     не доезжала вовсе (sendLead без contact только запоминает объект). Теперь прямо
     в карточке короткая форма: даты, гостей, как зовут и куда ответить — и заявка
     уходит. Эльнур: «можно набрать даты в календаре, а можно по карточке нажать
     и отправить запрос на объект, ответить на вопросы, и уйдёт заявка». */
  req.onclick=function(){
    var box=document.getElementById('bForm');
    if(box){ box.hidden=!box.hidden; if(!box.hidden){ var f=box.querySelector('input'); if(f) f.focus(); } return; }
    box=document.createElement('div'); box.id='bForm'; box.className='bform';
    box.innerHTML=
      '<div class="bf-row"><label>'+t('bf.guests')+'<input id="bfG" type="number" min="1" max="12" value="2"></label>'+
      '<label>'+t('bf.name')+'<input id="bfN" type="text" autocomplete="name"></label></div>'+
      '<label class="bf-full">'+t('bf.contact')+'<input id="bfC" type="text" inputmode="tel" '+
        'autocomplete="tel" placeholder="'+t('bf.cph')+'"></label>'+
      '<label class="bf-full">'+t('bf.note')+'<textarea id="bfT" rows="2" placeholder="'+t('bf.nph')+'"></textarea></label>'+
      '<button type="button" class="btn btn-primary btn-block" id="bfSend">'+t('bf.send')+'</button>'+
      '<p class="tnote" id="bfMsg"></p>';
    req.parentNode.insertBefore(box, req.nextSibling);
    document.getElementById('bfSend').onclick=function(){
      var c=(document.getElementById('bfC').value||'').trim();
      var msg=document.getElementById('bfMsg');
      if(c.replace(/\D/g,'').length<7 && c.indexOf('@')<0){ msg.textContent=t('bf.need'); return; }
      this.disabled=true; msg.textContent=t('bf.sending');
      var d=rentSelDates||null;
      var lead=pushLead({funnel:'rent',property_id:p.property_id,goal:'rent_request',
        name:(document.getElementById('bfN').value||'').trim()||null,
        contact:c, phone:c, guests:Number(document.getElementById('bfG').value||0)||null,
        note:[(d?('Даты: '+d.check_in+' → '+d.check_out):''),
              (document.getElementById('bfT').value||'').trim()].filter(Boolean).join(' · ')||null,
        check_in:d?d.check_in:null, check_out:d?d.check_out:null});
      var done=function(){ msg.textContent=t('bf.done'); box.querySelectorAll('input,textarea,button')
        .forEach(function(x){x.disabled=true;}); };
      if(lead&&lead.__send&&lead.__send.then) lead.__send.then(done)['catch'](done); else done();
    };
  };
}
/* Условия оплаты и рассрочка — на виду, а не под спойлером калькулятора:
   это первый вопрос покупателя после цены (Эльнур 05.09). */
function payPlanHTML(p){
  var c=(p&&p.calc)||{}, txt=(c.paymentPlan||'').trim();
  if(!txt) return '';
  /* «25% при контракте → 25% …» разбиваем на шаги, чтобы читалось глазами */
  var parts=txt.split(/\s*(?:→|\||;)\s*/).map(function(x){return x.trim();}).filter(Boolean);
  var steps=(parts.length>2)
    ? '<ol class="paysteps">'+parts.map(function(x){return '<li>'+escHTML(x)+'</li>';}).join('')+'</ol>'
    : '<p class="paytxt">'+escHTML(txt)+'</p>';
  return '<div class="payplan"><div class="th">🧾 '+t('pay.title')+
    (c.downPct?('<span class="pid">'+t('pay.first')+' '+c.downPct+'%</span>'):'')+'</div>'+
    steps+'<p class="tnote">'+t('pay.note')+'</p></div>';
}
function calcHTML(p){
  var c=p.calc,S=c.seasons;
  /* 21.09: калькулятор открывался и тогда, когда цены у объекта нет. У Gardens
     of Eden цену убрали из базы, а в расчёт тянулась прошлогодняя — 7,8 млн ฿:
     карточка честно писала «по запросу», а рядом считалась окупаемость по
     цифре, которой не существует. У Qabalah и Eden Lake в расчёт шёл ноль.
     Без цены считать нечего — говорим об этом прямо. */
  if(!(c && c.priceTHB > 0)){
    return '<div class="calc-none" style="margin-top:14px;padding:14px 16px;border-radius:12px;'+
      'background:rgba(var(--ink-rgb),.05);color:var(--muted);font-size:.92rem">'+
      'Расчёт доходности появится, когда застройщик подтвердит цену. '+
      'Напишите нам — пришлём актуальный прайс и посчитаем под вашу задачу.</div>';
  }
  function d(v,dflt){return v!=null?v:dflt;}
  function fld(id,label,val,step){return '<div class="fld"><label>'+label+'</label><input id="'+id+'" type="number" '+(step?('step="'+step+'" '):'')+'value="'+val+'"></div>';}
  function grp(title,inner){return '<div class="calc-grp"><div class="gh">'+title+'</div>'+inner+'</div>';}
  var sink=Math.round((c.capexM2||0)*(c.areaM2||0));           /* prefill фонда капремонта из capex×площадь */
  var longRent=Math.round(S.shoulder.rent);                    /* стартовая долгосрочная = shoulder */
  var seasonal='<div class="calc-inputs" id="segSeason">'+
    fld('cHigh',t('calc.high'),S.high.rent)+fld('cShoulder',t('calc.shoulder'),S.shoulder.rent)+fld('cLow',t('calc.low'),S.low.rent)+
    fld('cOccH',t('calc.occh'),S.high.occ,'0.1')+fld('cOccS',t('calc.occs'),S.shoulder.occ,'0.1')+fld('cOccL',t('calc.occl'),S.low.occ,'0.1')+
    fld('cMonH',t('calc.monh'),S.high.months)+fld('cMonS',t('calc.mons'),S.shoulder.months)+fld('cMonL',t('calc.monl'),S.low.months)+
    '</div>';
  var longt='<div class="calc-inputs" id="segLong" style="display:none">'+
    fld('cLong',t('calc.longrent'),longRent)+fld('cLongOcc',t('calc.longocc'),95,'0.1')+'</div>';
  var rentGrp=grp(t('grp.rent'),
    '<div class="calc-seg" id="cModeSeg"><button type="button" data-m="short" class="on">'+t('calc.modeS')+'</button><button type="button" data-m="long">'+t('calc.modeL')+'</button></div>'+
    seasonal+longt);
  var expGrp=grp(t('grp.exp'),'<div class="calc-inputs">'+
    fld('cMgmt',t('calc.mgmt'),c.mgmtPct,'0.1')+fld('cOta',t('calc.ota'),d(c.otaPct,15),'0.1')+
    fld('cMaint',t('calc.maint'),c.maintM2Month)+fld('cArea',t('calc.area'),c.areaM2)+
    fld('cMeters',t('calc.meters'),c.metersTHB)+fld('cTax',t('calc.tax'),d(c.taxPct,0),'0.1')+'</div>');
  var oneGrp=grp(t('grp.oneoff'),'<div class="calc-inputs">'+
    fld('cFurn',t('calc.furn'),d(c.furnitureTHB,0))+fld('cReg',t('calc.reg'),d(c.regTHB,0))+fld('cSink',t('calc.sink'),sink)+'</div>');
  var exitGrp=grp(t('grp.exit'),'<div class="calc-inputs">'+
    fld('cGrowth',t('calc.growth'),c.capGrowthPct,'0.1')+fld('cHorizon',t('calc.horizon'),d(c.horizonYears,5))+
    fld('cBuild',t('calc.build'),c.buildYears,'0.1')+fld('cExit',t('calc.exit'),d(c.exitPct,0),'0.1')+'</div>');
  var instGrp=grp(t('grp.inst'),'<div class="calc-inputs">'+
    fld('cHand',t('calc.handover'),c.handoverTHB)+fld('cDown',t('calc.down'),d(c.downPct,30),'0.1')+
    fld('cSt1',t('calc.st1'),d(c.stage1Pct,10),'0.1')+fld('cSt2',t('calc.st2'),d(c.stage2Pct,10),'0.1')+fld('cSt3',t('calc.st3'),d(c.stage3Pct,10),'0.1')+'</div>');
  var fxGrp=grp(t('grp.fx'),'<div class="calc-inputs">'+fld('cRate',t('calc.rate'),RATE,'0.1')+'</div>');
  return '<div class="toolbox"><div class="th">📈 '+t('calc.title')+'<span class="pid">'+p.property_id+'</span></div>'+
    '<div class="tnote" style="margin-bottom:10px">'+t('calc.hint')+'</div>'+
    (c.estimated?'<div class="tnote" style="margin-bottom:10px;color:#b8863b">⚠️ '+t('calc.estimated')+'</div>':'')+
    '<div class="calc-price-lead"><label>'+t('calc.price')+'</label><div class="prow"><input id="cPrice" type="number" value="'+c.priceTHB+'"><span class="usd" id="cUsd"></span></div>'+
    '<div class="calc-disc"><label>'+t('calc.disc')+'</label><input id="cDisc" type="number" step="0.1" value="'+d(c.discountPct,0)+'"><div class="calc-preset" id="cDiscPre"><button type="button" data-v="0">0</button><button type="button" data-v="5">5%</button><button type="button" data-v="10">10%</button></div><span class="disout" id="cDiscOut"></span></div></div>'+
    '<div class="calc-kpi" id="calcKpi"></div>'+
    '<details class="calc-more"><summary>'+t('calc.more')+' &#9662;</summary>'+
    rentGrp+expGrp+oneGrp+exitGrp+instGrp+fxGrp+'</details>'+
    '<div class="calc-out" id="calcOut"></div>'+
    '<div class="tnote">'+t('calc.note')+'</div></div>';
}
/* Виджет Дарьи: свернуть до значка и обратно. Свёрнутый разворачивается
   кликом по себе, поэтому кнопку чата в этом состоянии не открываем. */
function toggleFab(){
  var w=document.getElementById('fabWrap'); if(!w) return;
  var min=!w.classList.contains('min');
  w.classList.toggle('min',min);
  try{ localStorage.setItem('plp_fab_min', min?'1':'0'); }catch(e){}
}
function initFab(){
  var w=document.getElementById('fabWrap'), b=document.getElementById('fab');
  if(!w||!b) return;
  var min=false; try{ min=localStorage.getItem('plp_fab_min')==='1'; }catch(e){}
  if(min) w.classList.add('min');
  b.addEventListener('click',function(e){
    if(w.classList.contains('min')){ e.stopPropagation(); toggleFab(); }
  },true);
  /* Эльнур 04.09: сворачивать по наведению, а не кликом. Свёрнутый разворачивается
     наведением обратно — курсор на нём и так, клик открывает чат как прежде. */
  var t=null;
  w.addEventListener('mouseenter',function(){
    clearTimeout(t);
    if(w.classList.contains('min')) w.classList.remove('min');
  });
  w.addEventListener('mouseleave',function(){
    clearTimeout(t);
    t=setTimeout(function(){ w.classList.add('min'); },900);
  });
}
/* Текст из базы в разметку — только экранированным. */
function escHTML(x){return String(x==null?'':x).replace(/[&<>"]/g,function(ch){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch];});}
/* График рассрочки. Сверху — план застройщика дословно из базы, если он есть:
   это зафиксированная правда, её не разбираем и не пересказываем. Ниже таблица —
   прикидка: взносы разложены по сроку стройки (buildYears из даты сдачи).
   Сдан или дата сдачи неизвестна — этапов нет, весь расчёт при передаче. */
function schedHTML(base,downPct,s1,s2,s3,buildYears,plan,ready){
  base=Math.max(0,base||0);
  var planHTML = plan ? '<div class="calc-plan"><b>'+t('calc.schedplan')+'</b><p>'+escHTML(plan)+'</p></div>' : '';
  var months=Math.max(0,(buildYears||0)*12);
  if(months<1){
    // Стройки впереди нет — выдумывать этапы и даты нельзя.
    // Сдан — расчёт при передаче. Строится, но дата в базе прошла — честно
    // говорим, что срок уточняется, и не выдаём объект за сданный.
    if(!ready) return planHTML+'<div class="tnote">'+t('calc.schednodate')+'</div>';
    return planHTML+'<table class="calc-sched"><thead><tr><th>'+t('calc.sc.pay')+'</th><th class="num">'+t('calc.sc.pct')+'</th><th class="num">'+t('calc.sc.amt')+'</th></tr></thead><tbody>'+
      '<tr><td>'+t('calc.sc.keys')+'</td><td class="num">100%</td><td class="num">'+fmtTHB(base)+'</td></tr></tbody></table>'+
      '<div class="tnote">'+t('calc.schedready')+'</div>';
  }
  var keysPct=100-(downPct+s1+s2+s3),warn=keysPct<-0.001;if(keysPct<0)keysPct=0;
  var now=new Date();
  function addM(m){var x=new Date(now);x.setMonth(x.getMonth()+Math.round(m));return x;}
  function fd(x){return ('0'+(x.getMonth()+1)).slice(-2)+'.'+x.getFullYear();}
  var rows=[[t('calc.sc.down'),now,downPct],[t('calc.sc.stage')+' 1',addM(months/4),s1],[t('calc.sc.stage')+' 2',addM(months/2),s2],[t('calc.sc.stage')+' 3',addM(months*3/4),s3],[t('calc.sc.keys'),addM(months),keysPct]];
  var total=0,body='';
  rows.forEach(function(r){var amt=base*Math.max(0,r[2])/100;total+=amt;
    body+='<tr><td>'+r[0]+'</td><td>'+fd(r[1])+'</td><td class="num">'+(Math.max(0,r[2])).toFixed(0)+'%</td><td class="num">'+fmtTHB(amt)+'</td></tr>';});
  return planHTML+'<table class="calc-sched"><thead><tr><th>'+t('calc.sc.pay')+'</th><th>'+t('calc.sc.date')+'</th><th class="num">'+t('calc.sc.pct')+'</th><th class="num">'+t('calc.sc.amt')+'</th></tr></thead><tbody>'+body+
    '<tr class="total"><td>'+t('calc.sc.total')+'</td><td></td><td class="num">'+((downPct+s1+s2+s3+keysPct)).toFixed(0)+'%</td><td class="num">'+fmtTHB(total)+'</td></tr></tbody></table>'+
    (warn?'<div class="tnote" style="color:#b8863b">⚠️ '+t('calc.schedwarn')+'</div>':'')+'<div class="tnote">'+t('calc.schednote')+'</div>';
}
function wireCalc(p){
  var mode='short';
  var ids=['cPrice','cDisc','cHand','cHigh','cShoulder','cLow','cLong','cLongOcc','cMgmt','cOta','cMaint','cArea','cMeters','cTax','cFurn','cReg','cSink','cGrowth','cHorizon','cBuild','cExit','cDown','cSt1','cSt2','cSt3','cRate'];
  function num(id){var el=document.getElementById(id);return el?(+el.value||0):0;}
  function run(){
    var listed=num('cPrice'),handover=num('cHand'),rate=num('cRate')||RATE;
    var disc=Math.min(100,Math.max(0,num('cDisc')));
    var price=listed*(1-disc/100);   /* цена покупки со скидкой = база для доходности */
    var mgmt=Math.min(100,Math.max(0,num('cMgmt')));
    var r=calcEngine({price:price,mode:mode,longRent:num('cLong'),longOcc:num('cLongOcc'),
      high:num('cHigh'),shoulder:num('cShoulder'),low:num('cLow'),
      occH:num('cOccH'),occS:num('cOccS'),occL:num('cOccL'),monH:num('cMonH'),monS:num('cMonS'),monL:num('cMonL'),
      mgmt:mgmt,ota:num('cOta'),tax:num('cTax'),maint:num('cMaint'),area:num('cArea'),meters:num('cMeters')});
    var gross=r.gross,expenses=r.expenses,net=r.net,grossY=r.grossY,netY=r.netY,payback=r.payback;
    var horizon=Math.max(0,num('cHorizon')),build=num('cBuild');
    var rentYears=Math.max(0,horizon-build);
    var growth=num('cGrowth')/100;
    var valueEnd=handover*Math.pow(1+growth,rentYears);
    var capGain=valueEnd-price;
    var exitFee=valueEnd*Math.max(0,num('cExit'))/100;
    var oneOff=num('cFurn')+num('cReg')+num('cSink');
    var rentalTotal=net*rentYears;
    var fullInc=rentalTotal+capGain-oneOff-exitFee;
    var roi5=price>0?(capGain+rentalTotal)/price*100:0;   /* для разбора Дарьи (сохранена семантика) */
    var usd=document.getElementById('cUsd');
    if(usd)usd.textContent=listed>0?tpl('calc.usd',{v:Math.round(listed/rate).toLocaleString('en-US'),r:rate}):'';
    var dout=document.getElementById('cDiscOut');
    if(dout)dout.textContent=disc>0?tpl('calc.discp',{b:fmtTHB(price),u:Math.round(price/rate).toLocaleString('en-US')}):'';
    var pre=document.getElementById('cDiscPre');
    if(pre)pre.querySelectorAll('button').forEach(function(b){b.classList.toggle('on',+b.dataset.v===disc);});
    /* Ставок аренды по объекту может не быть — тогда расчёт уходил в минус и
       на витрине висело «฿-15 000 чистыми/год». Пока ставки не вписаны,
       показываем прочерк и просим их указать (Эльнур 05.09). */
    var noRates = !(gross>0);
    /* Ставок нет — сразу открываем параметры и подсвечиваем поля аренды,
       чтобы цифру можно было посчитать, а не смотреть на прочерк. */
    if(noRates){
      var box=document.querySelector('#pmTool .calc-more, .calc-more');
      if(box && !box.__opened){ box.__opened=1; box.open=true; }
      var seg=document.getElementById('segSeason');
      if(seg) seg.classList.add('needfill');
    }
    /* Эльнур 06.09: «либо пиши настоящие цифры после тщательного анализа, либо
       вообще не пиши и не пугай». Окупаемость под 50 лет означает одно: ставки
       аренды по объекту ещё не выверены с рынком. Такие цифры на витрину не
       выпускаем — вместо них честное «считаем точно». */
    /* Пороги задал Эльнур 06.09: доходность 4–15% годовых, окупаемость не
       больше 12 лет. Цифры вне этих рамок значат, что ставки по объекту ещё не
       выверены, — клиент не должен видеть «49 лет» и уходить.
       Арифметика: 12 лет окупаемости — это 8,3% годовых, поэтому плитку срока
       показываем только у самых доходных, а доходность 4–15% сама по себе
       честная и остаётся на месте. */
    var cc=(p&&p.calc)||{};
    var yieldOk = !cc.estimated && netY>=4 && netY<=15;
    var backOk  = yieldOk && payback>0 && payback<=12;
    window.__calcTrusted = yieldOk;
    document.getElementById('calcKpi').innerHTML= noRates
      ? '<div class="kpi wide"><div class="kv">—</div><div class="kl">'+t('calc.norates')+'</div></div>'
      : (yieldOk
         ? ('<div class="kpi"><div class="kv">'+fmtTHB(net)+'</div><div class="kl">'+t('calc.netyr')+'</div></div>'+
            '<div class="kpi"><div class="kv">'+netY.toFixed(1)+'%</div><div class="kl">'+t('calc.netyield')+'</div></div>'+
            (backOk
              ? '<div class="kpi"><div class="kv">'+payback.toFixed(1)+' '+t('calc.years')+'</div><div class="kl">'+t('calc.payback')+'</div></div>'
              : '<div class="kpi"><div class="kv">'+fmtTHB(net*5)+'</div><div class="kl">'+t('calc.net5')+'</div></div>'))
         : ('<div class="kpi"><div class="kv">'+fmtTHB(net)+'</div><div class="kl">'+t('calc.netyr')+'</div></div>'+
            '<div class="kpi wide"><div class="kv">'+t('calc.checkv')+'</div><div class="kl">'+t('calc.checkl')+'</div></div>'));
    document.getElementById('calcOut').innerHTML=
      '<div class="big"><span class="k">'+tpl('calc.fullinc',{n:horizon})+'</span><span class="v">'+fmtTHB(fullInc)+'</span></div>'+
      '<div class="row grow" style="margin-top:6px"><span>'+tpl('calc.capgain',{n:horizon})+'</span><b>+'+fmtTHB(capGain)+'</b></div>'+
      '<div class="row"><span>'+t('calc.gross')+'</span><b>'+fmtTHB(gross)+'</b></div>'+
      '<div class="row"><span>'+t('calc.expenses')+'</span><b>−'+fmtTHB(expenses)+'</b></div>'+
      '<div class="row"><span>'+t('calc.grossyield')+'</span><b>'+grossY.toFixed(1)+'%</b></div>'+
      '<details class="calc-more"><summary>'+t('calc.schedttl')+' &#9662;</summary>'+schedHTML(price,num('cDown'),num('cSt1'),num('cSt2'),num('cSt3'),build,((p&&p.calc)||{}).paymentPlan,((p&&p.calc)||{}).ready||(p&&p.ready))+'</details>'+
      '<div class="ai-verdict" id="aiVerdict"><button type="button" class="ai-ask" onclick="askVerdict()">'+t('calc.ask')+'</button></div>';
    window.__calcSnapshot={pid:p&&p.property_id,gross:gross,expenses:expenses,net:net,grossY:grossY,netY:netY,payback:payback,roi5:roi5,fullInc:fullInc,horizon:horizon,price:price,handover:handover,mgmt:mgmt,build:build,mode:mode};
  }
  var pre=document.getElementById('cDiscPre');
  if(pre)pre.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){
    var di=document.getElementById('cDisc');if(di){di.value=b.dataset.v;}run();
  });});
  var seg=document.getElementById('cModeSeg');
  if(seg)seg.querySelectorAll('button').forEach(function(b){b.addEventListener('click',function(){
    mode=b.dataset.m;
    seg.querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===b);});
    var ss=document.getElementById('segSeason'),sl=document.getElementById('segLong');
    if(ss)ss.style.display=mode==='long'?'none':'';
    if(sl)sl.style.display=mode==='long'?'':'none';
    run();
  });});
  ids.concat(['cOccH','cOccS','cOccL','cMonH','cMonS','cMonL']).forEach(function(id){var el=document.getElementById(id);if(el)el.addEventListener('input',run);});
  run();
}
/* Разбор доходности словами — локальные правила (пороги рынка: net 6–8% норма, >8% сильно, <5% слабо) */
function askVerdict(){
  var box=document.getElementById('aiVerdict');var s=window.__calcSnapshot;if(!box||!s)return;
  // TODO: POST -> n8n webhook (живой разбор от brain_core / Дарьи)
  var strong=[],risks=[],total;
  if(s.netY>=8)strong.push(t('v.y.hi'));
  else if(s.netY>=6)strong.push(t('v.y.mid'));
  if(s.roi5>=60)strong.push(t('v.roi.hi'));
  if(!strong.length)strong.push(t('v.roi.lo'));
  risks.push(t('v.r.occ'));
  if(s.netY<5)risks.push(t('v.y.lo'));
  else if(s.build>=1)risks.push(t('v.r.build'));
  total=(s.netY>=5?t('v.t.mid'):t('v.t.lo'));
  if(s.roi5!=null&&isFinite(s.roi5)){   /* явно про полный доход с учётом роста */
    total+='. '+tpl('v.fi',{r:s.roi5.toFixed(0),n:s.horizon!=null?s.horizon:5})+(s.roi5>=60?t('v.fi.hi'):t('v.fi.lo'));
  }
  function block(k,v){return '<div class="avr"><span class="ak">'+k+'</span><span class="av">'+v+'</span></div>';}
  box.innerHTML='<div class="ai-txt">'+
    block(t('v.strong'),strong.join('; '))+
    block(t('v.risks'),risks.join('; '))+
    block(t('v.total'),total)+
    '</div><div class="tnote" style="margin-top:8px">'+t('v.note')+'</div>';
}

/* ===== YIELD ENGINE (общий движок: карточка объекта + чат Дарьи) ===== */
function fmtSp(n){n=Math.round(n||0);var s=String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g,' ');return (n<0?'\u2212':'')+s;}
function fmtBt(n){return '\u0e3f'+fmtSp(n);}
function tpl(k,map){var s=t(k);Object.keys(map).forEach(function(x){s=s.split('{'+x+'}').join(map[x]);});return s;}
function calcEngine(v){
  var gross;
  if(v.mode==='long'){gross=(v.longRent||0)*12*Math.min(100,Math.max(0,v.longOcc||0))/100;}
  else{gross=v.high*v.monH*v.occH/100+v.shoulder*v.monS*v.occS/100+v.low*v.monL*v.occL/100;}
  var ota=(v.mode==='long')?0:gross*Math.max(0,v.ota||0)/100;   /* OTA только для краткосрока */
  var tax=gross*Math.max(0,v.tax||0)/100;
  var expenses=gross*Math.min(100,Math.max(0,v.mgmt))/100+ota+tax+(v.maint||0)*(v.area||0)*12+(v.meters||0);
  var net=gross-expenses;
  return {gross:gross,expenses:expenses,net:net,
    netY:v.price>0?net/v.price*100:0,grossY:v.price>0?gross/v.price*100:0,
    payback:net>0?v.price/net:0};
}
function calcFromData(c){
  var S=c.seasons;
  return calcEngine({price:c.priceTHB,high:S.high.rent,shoulder:S.shoulder.rent,low:S.low.rent,
    occH:S.high.occ,occS:S.shoulder.occ,occL:S.low.occ,monH:S.high.months,monS:S.shoulder.months,monL:S.low.months,
    mgmt:c.mgmtPct,maint:c.maintM2Month,area:c.areaM2,meters:c.metersTHB});
}

/* ===== SALE FILTERS / SEARCH / SORT ===== */
var activeFilter={budget:'',loc:new Set(),type:new Set(),stage:new Set(),beds:new Set()};
var saleQuery='',favOnly=false;
/* Панель уже свёрнута в меню? Разворачиваем обратно, чтобы пересобрать её
   заново. Без этого чипы районов, созданные после группировки, ложились в
   корень панели полотном мимо выпадающих списков. */
function ungroupFilters(bar){
  if(!bar || !bar.dataset.grouped) return;
  var chips=Array.prototype.slice.call(bar.querySelectorAll('.chipf'));
  var rest=Array.prototype.slice.call(bar.children).filter(function(e){
    return !e.classList.contains('fmenu') && !e.classList.contains('fbtn-reset');
  });
  bar.innerHTML='';
  chips.forEach(function(c){ bar.appendChild(c); });
  rest.forEach(function(e){ bar.appendChild(e); });
  delete bar.dataset.grouped; bar.classList.remove('fbar-menus');
}
function buildLocChips(){
  var bar=document.getElementById('saleFilters');if(!bar)return;
  ungroupFilters(bar);
  bar.querySelectorAll('[data-facet="loc"]').forEach(function(c){c.remove();});
  var seen=new Map();PL.PROPERTIES.forEach(function(p){seen.set(p.loc.ru,loc(p.loc));});
  var anchor=bar.querySelector('[data-facet="type"]');
  seen.forEach(function(label,val){
    var s=document.createElement('span');
    s.className='chipf'+(activeFilter.loc.has(val)?' on':'');
    s.dataset.facet='loc';s.dataset.val=val;s.textContent=label;
    s.onclick=function(){toggleFilter(s);};
    bar.insertBefore(s,anchor);
  });
}
var activeRent={loc:new Set(),type:new Set(),beds:new Set(),amen:new Set()};
/* доступность по датам: null = фильтр выключен (все свободны); иначе Set свободных property_id */
var rentAvailable=null;
var rentSelDates=null; /* выбранные даты заезда/выезда — переносим в заявку на аренду */
/* Эльнур 08.09: у лида на аренду не было своей полосы — заявка падала в воронку
   и ждала человека. Теперь из чата можно закрепить конкретные даты за объектом. */
var bookCtx=null;
/* удобства: ключ → регэксп по тексту (amenities + rent_included + desc), RU+EN. Без выдумок:
   если у объекта нет данных об удобствах — он не отсеивается (мягкое совпадение, помечается бейджем). */
var RENT_AMEN=[
  {id:'pool',re:/бассейн|pool/i},
  {id:'beach',re:/перв\S*\s*лини|у моря|на берегу моря|на берегу\b|beach\s?front|first\s?line|у самого моря/i},
  {id:'parking',re:/парковк|паркинг|parking|гараж|garage/i},
  {id:'gym',re:/спортзал|тренаж|фитнес|gym\b|fitness/i},
  {id:'pets',re:/pet[-\s]?friendly|питом|можно с животными|разрешены животные|с животными можно|pets allowed/i}
];
/* флаги удобств объекта. hasData=есть текстовый источник (amenities|rent_included) → можно отсеивать строго.
   Нет текста → hasData=false → по удобствам не режем (мягко), но позитивные признаки (вилла→бассейн,
   distance_beach_m→у моря) всё равно засчитываем как совпадение. */
function rentAmenInfo(p){
  var set=new Set();
  if(!p)return{set:set,hasData:false};
  var base=[p.amenities,p.included].filter(Boolean).join(' ').trim();
  var txt=[p.amenities,p.included,p.desc&&p.desc.ru,p.desc&&p.desc.en].filter(Boolean).join(' ');
  RENT_AMEN.forEach(function(a){if(a.re.test(txt))set.add(a.id);});
  /* точечная защита от отрицаний: снимаем флаг, если рядом явное «без …» этого удобства */
  if(/без бассейн|no pool/i.test(txt))set.delete('pool');
  if(/без парковк|no parking/i.test(txt))set.delete('parking');
  if(/без животных|no pets|pets not allowed|нельзя с животными/i.test(txt))set.delete('pets');
  if(/без спортзал|no gym/i.test(txt))set.delete('gym');
  /* позитивные деривации (не вызывают отсева, только добавляют совпадение) */
  if(p.beach_m!=null&&p.beach_m<=150)set.add('beach');
  if(p.type&&p.type.ru==='Вилла'&&!/без бассейн|no pool/i.test(txt))set.add('pool');
  return{set:set,hasData:base.length>0};
}
/* совпадение по спальням: val = '1'|'2'|'3'|'4' (4 = 4+). Неизвестно → true (не режем). */
function rentBedsMatch(p,val){
  var n=parseInt(val,10);var lo=p&&p.bmin,hi=p&&p.bmax;
  if(lo==null&&hi==null){
    var m=(p&&p.beds||'').match(/\d+/g);
    if(!m){if(/студи|studio/i.test(p&&p.beds||''))lo=hi=0;else return true;}
    else{lo=parseInt(m[0],10);hi=parseInt(m[m.length-1],10);}
  }
  if(lo==null)lo=hi;if(hi==null)hi=lo;
  if(val==='4')return hi>=4;
  return lo<=n&&n<=hi;
}
function buildRentChips(){
  var bar=document.getElementById('rentFilters');if(!bar)return;
  bar.innerHTML='';
  /* строим заново — значит и сворачивать в меню надо заново */
  delete bar.dataset.grouped; bar.classList.remove('fbar-menus');
  function group(labelKey,parent){
    var host=parent||bar;
    var g=document.createElement('div');g.className='rf-group';
    g.dataset.gkey=labelKey;   /* по ключу узнаём фильтр, когда группа уезжает в меню */
    var l=document.createElement('div');l.className='rf-label';l.textContent=t(labelKey);
    var row=document.createElement('div');row.className='rf-chips';
    g.appendChild(l);g.appendChild(row);host.appendChild(g);return row;
  }
  function chip(row,f,val,label){
    var s=document.createElement('span');
    s.className='chipf'+(activeRent[f].has(val)?' on':'');
    s.dataset.facet=f;s.dataset.val=val;s.textContent=label;
    s.onclick=function(){var set=activeRent[f];if(set.has(val))set.delete(val);else set.add(val);s.classList.toggle('on');applyRentFilters();};
    row.appendChild(s);
  }
  /* НА ВИДУ: район. Показываем ВСЕ районы, где мы работаем, а не только те три,
     где сегодня есть свободная аренда: иначе список выглядит куцым и человек
     думает, что остров у нас кончается. Районы без предложений — неактивные,
     с честной подписью, а не обманкой. */
  var locs=new Map();PL.RENTALS.forEach(function(p){locs.set(p.loc.ru,loc(p.loc));});
  var all=new Map(locs);
  (PL.PROPERTIES||[]).forEach(function(p){ if(!all.has(p.loc.ru)) all.set(p.loc.ru,loc(p.loc)); });
  if(all.size){
    var rl=group('rent.f.district');
    var keys=Array.from(all.keys()).sort(function(a,b){
      var ea=locs.has(a), eb=locs.has(b);          /* сначала те, где есть что снять */
      if(ea!==eb) return ea?-1:1;
      return String(all.get(a)).localeCompare(String(all.get(b)),'ru');
    });
    keys.forEach(function(val){
      if(locs.has(val)){ chip(rl,'loc',val,all.get(val)); return; }
      var s=document.createElement('span');
      s.className='chipf off'; s.textContent=all.get(val);
      s.title=t('rent.f.nofree');
      rl.appendChild(s);
    });
  }
  /* Порядок тот же, что в продаже: Район → Тип → Спальни → (Удобства).
     Спойлер «Больше фильтров» убран: все фасеты и так сворачиваются в
     одинаковые кнопки-меню, а прятать половину фильтров — расхождение. */
  var types=new Map();PL.RENTALS.forEach(function(p){types.set(p.type.ru,loc(p.type));});
  if(types.size){var rt=group('rent.f.type');types.forEach(function(label,val){chip(rt,'type',val,label);});}
  var rb=group('rent.f.beds');
  ['1','2','3'].forEach(function(v){chip(rb,'beds',v,v);});
  chip(rb,'beds','4',t('rent.beds.4'));
  /* удобства — чекбоксы */
  var ra=group('rent.f.amen');
  RENT_AMEN.forEach(function(a){
    var lab=document.createElement('label');
    lab.className='rf-check'+(activeRent.amen.has(a.id)?' on':'');
    var inp=document.createElement('input');inp.type='checkbox';inp.checked=activeRent.amen.has(a.id);inp.dataset.amen=a.id;
    var sp=document.createElement('span');sp.textContent=t('rent.am.'+a.id);
    inp.onchange=function(){if(inp.checked)activeRent.amen.add(a.id);else activeRent.amen.delete(a.id);lab.classList.toggle('on',inp.checked);applyRentFilters();};
    lab.appendChild(inp);lab.appendChild(sp);ra.appendChild(lab);
  });
  /* сброс фильтров (на виду; даты сбрасываются отдельной кнопкой) */
  /* кнопка та же, что в продаже: одинаковая система — одинаковые органы управления */
  var rs=document.createElement('button');
  rs.type='button'; rs.className='fbtn fbtn-reset'; rs.textContent='Сбросить';
  rs.onclick=resetRentFilters; bar.appendChild(rs);
}
function resetRentFilters(){
  activeRent.loc.clear();activeRent.type.clear();activeRent.beds.clear();activeRent.amen.clear();
  rentQuery=''; rentPriceRange=null;
  var q=document.getElementById('rentSearch'); if(q) q.value='';
  var so=document.getElementById('rentSort'); if(so){ so.value=''; try{ setRentSort(''); }catch(e){} }
  buildRentChips();applyRentFilters();finishRentFilters();
}
/* после сборки фильтров аренды сворачиваем их в меню */
function finishRentFilters(){ try{ groupRentMenus(); }catch(e){} }

function applyRentFilters(){
  var visible=0,freeVisible=0,noPriceCount=0;
  document.querySelectorAll('#rentCar .prop').forEach(function(el){
    var pid=el.dataset.pid;var p=pid?PL.byId[pid]:null;
    var okL=activeRent.loc.size===0||activeRent.loc.has(el.dataset.loc);
    var okT=activeRent.type.size===0||activeRent.type.has(el.dataset.type);
    var okB=activeRent.beds.size===0||Array.prototype.some.call(Array.from(activeRent.beds),function(v){return rentBedsMatch(p,v);});
    var okA=true,soft=false;
    if(activeRent.amen.size){
      var info=rentAmenInfo(p);
      okA=Array.from(activeRent.amen).every(function(a){return info.set.has(a)||!info.hasData;});
      /* мягкое совпадение: прошёл только из-за отсутствия данных → пометить бейджем */
      if(okA)soft=Array.from(activeRent.amen).some(function(a){return !info.set.has(a)&&!info.hasData;});
    }
    /* те же условия, что и в продаже: строка поиска и режим «только избранное» */
    var okQ=true;
    if(rentQuery && rentQuery.trim()){
      var q=rentQuery.trim().toLowerCase();
      okQ=((p&&p.title)||'').toLowerCase().indexOf(q)>=0 ||
          ((p&&p.loc&&loc(p.loc))||'').toLowerCase().indexOf(q)>=0 ||
          String(pid||'').toLowerCase().indexOf(q)>=0;
    }
    var okF=!favOnly || (pid && FAVS.has(pid));
    /* Бюджет: сравниваем в выбранной единице (ночь или месяц). Объект без ставки
       не выбрасываем — показываем с пометкой «цена по запросу», иначе человек
       решит, что предложений нет. */
    var okP=true, noPrice=false;
    if(rentPriceRange && p){
      var rate=rentRate(p,rentUnit), top=rentRateTop(p,rentUnit);
      if(p.notReady){ soft=true; }                    /* строится — не «цена по запросу» */
      else if(rate===null){ soft=true; noPrice=true; }
      /* ставка меняется по сезонам: объект подходит, если его вилка
         пересекается с бюджетом, а не только нижняя цена */
      else okP = rate<=rentPriceRange.to && top>=rentPriceRange.from;
    }
    var vis=okL&&okT&&okB&&okA&&okQ&&okF&&okP;
    el.style.display=vis?'':'none';
    el.classList.toggle('softmatch',vis&&soft);
    el.classList.toggle('noprice',vis&&noPrice);
    if(vis&&soft){
      var wn=el.querySelector('.amwarn');
      if(wn) wn.textContent = p&&p.notReady ? rentSoonText(p)
                            : (noPrice ? t('rent.noprice') : t('rent.am.soft'));
    }
    if(vis&&noPrice) noPriceCount++;
    var pic=el.querySelector('.pic');
    if(vis){
      visible++;
      if(rentAvailable&&pid){
        var free=rentAvailable.has(pid);
        el.classList.toggle('booked',!free);
        if(pic)pic.setAttribute('data-busy',t('rent.dates.busy'));
        if(free)freeVisible++;
      }else{
        el.classList.remove('booked');
        if(pic)pic.removeAttribute('data-busy');
        freeVisible++;
      }
    }else{
      el.classList.remove('booked');el.classList.remove('softmatch');
    }
  });
  var nr=document.getElementById('rentNoResult');if(nr)nr.style.display=visible?'none':'block';
  var rf=document.getElementById('rentFound');
  if(rf){
    /* 21.09: слово «объект» подставлялось всегда по-русски, и на английской
       версии выходило «50 объектов match your filters». */
    var txt = (PL.lang==='en')
      ? (visible + ' ' + (visible===1?'property':'properties') + ' ' + t('f.found'))
      : (visible + ' ' + plural(visible,'объект','объекта','объектов') + ' ' + t('f.found'));
    /* при заданном бюджете честно говорим, сколько из них — «цена по запросу»:
       выбрасывать их нельзя (цена может подойти), но и молчать нечестно */
    if(rentPriceRange && noPriceCount) txt += ' · ' + noPriceCount + ' — ' + t('rent.noprice');
    rf.textContent = txt;
  }
  /* подходящие по цене — вперёд, «по запросу» — в конец ленты */
  if(rentPriceRange){
    var carEl=document.getElementById('rentCar');
    if(carEl) Array.prototype.slice.call(carEl.querySelectorAll('.prop.noprice')).forEach(function(el){
      carEl.appendChild(el);
    });
  }
  if(rentAvailable&&visible){
    var st=document.getElementById('rentDateStatus');
    if(st){
      if(freeVisible===0){st.className='df-status err';st.textContent=t('rent.dates.none');}
      else{st.className='df-status ok';st.textContent=t('rent.dates.free');}
    }
  }
}
/* ===== ОДНО ПОЛЕ «ЗАЕЗД И ВЫЕЗД» =====
   Эльнур 08.09: «заезд выезд везде должны проставляться в одном поле».
   Один виджет на весь сайт: кнопка показывает выбранный промежуток, под ней
   календарь — первое нажатие ставит заезд, второе выезд. Значения по-прежнему
   лежат в полях с прежними именами, поэтому всё, что их читало, работает как
   раньше: мы просто шлём им событие change. */
function rfISO(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function rfLoc(){return PL.lang==='en'?'en-GB':'ru-RU';}
function rfDay(iso){try{return new Date(iso+'T00:00:00').toLocaleDateString(rfLoc(),{day:'numeric',month:'short'});}catch(e){return iso;}}
function rfNights(n){
  if(PL.lang!=='ru') return n+' '+t(n===1?'rent.dates.n1':'rent.dates.n2');
  var a=n%10,b=n%100;
  var k = (a===1&&b!==11)?'rent.dates.n1':((a>=2&&a<=4&&(b<10||b>=20))?'rent.dates.n2':'rent.dates.n5');
  return n+' '+t(k);
}
function mkRangeField(o){
  var A=document.getElementById(o.inId), B=document.getElementById(o.outId),
      btn=document.getElementById(o.btnId), cal=document.getElementById(o.calId),
      lab=document.getElementById(o.labelId);
  if(!A||!B||!btn||!cal||!lab) return null;
  var today=rfISO(new Date()), month=null;
  function label(){
    if(A.value&&B.value){
      var n=Math.round((new Date(B.value+'T00:00:00')-new Date(A.value+'T00:00:00'))/86400000);
      lab.textContent=rfDay(A.value)+' — '+rfDay(B.value)+(n>0?(' · '+rfNights(n)):'');
    } else if(A.value){ lab.textContent=rfDay(A.value)+' — '+t('rent.dates.pickout'); }
    else { lab.textContent=t('rent.dates.pick'); }
  }
  function draw(){
    var base = month || (A.value?new Date(A.value+'T00:00:00'):new Date());
    month=new Date(base.getFullYear(), base.getMonth(), 1);
    var y=month.getFullYear(), m=month.getMonth();
    var start=(new Date(y,m,1).getDay()+6)%7, days=new Date(y,m+1,0).getDate();
    var wd='';
    for(var w=0;w<7;w++) wd+='<span>'+new Date(2024,0,1+w).toLocaleDateString(rfLoc(),{weekday:'short'})+'</span>';
    var cells='';
    for(var i=0;i<start;i++) cells+='<span class="rf-e"></span>';
    for(var d=1;d<=days;d++){
      var iso=y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
      var cls='';
      if(iso<today) cls=' rf-off';
      else if(iso===A.value||iso===B.value) cls=' rf-edge';
      else if(A.value&&B.value&&iso>A.value&&iso<B.value) cls=' rf-in';
      cells+='<span class="'+cls.trim()+'" data-d="'+iso+'">'+d+'</span>';
    }
    cal.innerHTML='<div class="rf-h"><button type="button" class="rf-nav" data-rf="-1">‹</button>'+
      '<b>'+month.toLocaleDateString(rfLoc(),{month:'long',year:'numeric'})+'</b>'+
      '<button type="button" class="rf-nav" data-rf="1">›</button></div>'+
      '<div class="rf-w">'+wd+'</div><div class="rf-g">'+cells+'</div>';
  }
  function fire(el){
    try{ el.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){}
    try{ el.dispatchEvent(new Event('change',{bubbles:true})); }catch(e){}
  }
  function pick(iso){
    if(iso<today) return;
    if(!A.value || (A.value&&B.value) || iso<=A.value){ A.value=iso; B.value=''; fire(A); fire(B); }
    else { B.value=iso; fire(B); }
    draw(); label();
    if(A.value&&B.value){ cal.hidden=true; btn.classList.remove('open'); }
  }
  btn.onclick=function(){ cal.hidden=!cal.hidden; btn.classList.toggle('open',!cal.hidden); if(!cal.hidden) draw(); };
  cal.onclick=function(e){
    var nav=e.target.closest&&e.target.closest('[data-rf]');
    if(nav){ month=new Date(month.getFullYear(), month.getMonth()+Number(nav.getAttribute('data-rf')),1); draw(); return; }
    var day=e.target.closest&&e.target.closest('[data-d]');
    if(day) pick(day.getAttribute('data-d'));
  };
  /* если даты сбросили снаружи (кнопка «Сбросить»), надпись обновится сама */
  A.addEventListener('change', label); B.addEventListener('change', label);
  label(); draw();
  return {refresh:function(){ label(); draw(); }};
}
/* ===== КЛИЕНТСКИЙ ФИЛЬТР ДАТ АРЕНДЫ (сверка с бронями через WF_availability) ===== */
var RENT_RF=null;
function initRentDates(){
  var ci=document.getElementById('rentIn'),co=document.getElementById('rentOut'),btn=document.getElementById('rentCheck');
  if(!ci||!co||!btn)return;
  function sync(){ btn.disabled=!(ci.value&&co.value&&co.value>ci.value); }
  ci.addEventListener('change',sync); co.addEventListener('change',sync);
  RENT_RF=mkRangeField({inId:'rentIn',outId:'rentOut',btnId:'rentRangeBtn',
                        calId:'rentRangeCal',labelId:'rentRangeT'});
  sync();
}
function rentDateStatus(cls,key){var st=document.getElementById('rentDateStatus');if(!st)return;st.className='df-status'+(cls?(' '+cls):'');st.textContent=t(key);}
function checkAvailability(){
  var ci=document.getElementById('rentIn'),co=document.getElementById('rentOut');
  if(!ci||!co||!ci.value||!co.value||co.value<=ci.value)return;
  rentSelDates={check_in:ci.value,check_out:co.value};
  rentDateStatus('loading','rent.dates.loading');
  document.getElementById('rentReset').style.display='';
  fetch(AVAIL_ENDPOINT+'&check_in='+encodeURIComponent(ci.value)+'&check_out='+encodeURIComponent(co.value))
    .then(function(r){return r.json();})
    .then(function(d){
      if(!d||d.ok!==true||!Array.isArray(d.available))throw new Error('bad response');
      rentAvailable=new Set(d.available);
      applyRentFilters(); /* сам выставит статус: свободно / нет вариантов */
    })
    .catch(function(){
      /* мягкая деградация: сеть/сервер недоступны — показываем все */
      rentAvailable=null;applyRentFilters();
      rentDateStatus('err','rent.dates.err');
    });
}
function resetAvailability(){
  var ci=document.getElementById('rentIn'),co=document.getElementById('rentOut');
  if(ci)ci.value='';if(co)co.value='';
  rentAvailable=null;rentSelDates=null;
  var btn=document.getElementById('rentCheck');if(btn)btn.disabled=true;
  document.getElementById('rentReset').style.display='none';
  if(RENT_RF) RENT_RF.refresh();
  applyRentFilters();
  rentDateStatus('','rent.dates.hint');
}
/* Панель фильтров: вместо длинной ленты чипов — компактные кнопки с
   выпадающими списками. Раскрываются по наведению курсора, на телефоне —
   по касанию. Сами чипы остаются те же, меняется только их расположение,
   поэтому вся логика фильтрации работает как прежде. */
var FILTER_MENUS=[
  {key:'budget', label:'Бюджет'},
  {key:'loc',    label:'Район'},
  {key:'type',   label:'Тип'},
  {key:'beds',   label:'Спальни', extra:[
      {v:'0',t:'Студия'},{v:'1',t:'1'},{v:'2',t:'2'},{v:'3',t:'3'},{v:'4',t:'4 и больше'}]},
  {key:'stage',  label:'Стадия'}
];
/* Аренда рисует фильтры своими группами «подпись + чипы» — сворачиваем их
   в такие же кнопки с выпадающим списком, чтобы поведение было одинаковым. */
/* Компактная строка фильтров на телефоне: главные видны, прочие — под «Ещё». */
/* Кнопка «Фильтры» и выезжающая панель на телефоне */
function filterSheet(barId){
  /* Эльнур 06.09: «липучка выглядит ужасно, верни как было». Фильтры остаются
     строкой; что не влезло — раскрывается кнопкой «Ещё фильтры». */
  var bar=document.getElementById(barId); if(!bar) return;
  bar.classList.remove('sheet-open');
  var old=bar.parentNode.querySelector('.fbar-open'); if(old) old.remove();
  var head=bar.querySelector('.fbar-head'); if(head) head.remove();
  var back=document.querySelector('.fbar-backdrop'); if(back) back.remove();
  /* поиск и сортировка возвращаются на своё место */
  var tools=bar.querySelector('.sheet-tools');
  if(tools){
    var sec=bar.closest('section')||bar.parentNode;
    var toolbar=sec.querySelector('.toolbar');
    if(toolbar){ while(tools.firstChild) toolbar.appendChild(tools.firstChild); }
    tools.remove();
  }
  document.body.style.overflow='';
}
function updateFilterCount(barId){
  var bar=document.getElementById(barId); if(!bar) return;
  var btn=bar.parentNode.querySelector('.fbar-open'); if(!btn) return;
  var n=bar.querySelectorAll('.fmenu.has').length;
  var b=btn.querySelector('.n');
  b.textContent=n; b.hidden=!n;
}
function compactFilters(barId){
  var bar=document.getElementById(barId); if(!bar) return;
  if(!window.matchMedia || !window.matchMedia('(max-width:600px)').matches){
    bar.classList.remove('compact'); return;
  }
  var menus=Array.prototype.slice.call(bar.querySelectorAll('.fmenu'));
  if(menus.length<4) return;
  /* Эльнур 06.09: в строке ровно «Бюджет · Район · Ещё фильтры» — три кнопки в один ряд */
  var keep=['budget','loc','rentbudget'];
  menus.forEach(function(m){
    var f=m.dataset.facet||'';
    if(keep.indexOf(f)<0) m.classList.add('hide-sm');
  });
  if(!bar.querySelector('.fbtn-more')){
    var more=document.createElement('button');
    more.type='button'; more.className='fbtn-more'; more.textContent='Ещё фильтры';
    more.onclick=function(){
      var on=bar.classList.toggle('compact');
      more.textContent = on ? 'Ещё фильтры' : 'Свернуть фильтры';
    };
    var reset=bar.querySelector('.fbtn-reset');
    bar.insertBefore(more, reset||null);
  }
  bar.classList.add('compact');
}
function groupRentMenus(){
  var bar=document.getElementById('rentFilters');
  if(!bar || bar.dataset.grouped) return;
  var groups=Array.prototype.slice.call(bar.querySelectorAll('.rf-group'));
  if(!groups.length) return;
  var extra=Array.prototype.slice.call(bar.children).filter(function(e){ return !e.classList.contains('rf-group'); });
  bar.innerHTML=''; bar.dataset.grouped='1'; bar.classList.add('fbar-menus');
  groups.forEach(function(g){
    var label=(g.querySelector('.rf-label')||{}).textContent||'Фильтр';
    var chips=g.querySelector('.rf-chips');
    var wrap=document.createElement('div'); wrap.className='fmenu';
    var gk=(g.dataset.gkey||'').split('.').pop();
    wrap.dataset.facet = (gk==='district') ? 'loc' : gk;
    var btn=document.createElement('button'); btn.type='button'; btn.className='fbtn';
    btn.innerHTML='<span class="fb-t">'+label+'</span><span class="fb-v"></span><i>▾</i>';
    var pan=document.createElement('div'); pan.className='fpan';
    if(chips) Array.prototype.slice.call(chips.children).forEach(function(c){ pan.appendChild(c); });
    wrap.appendChild(btn); wrap.appendChild(pan); bar.appendChild(wrap);
    btn.onclick=function(e){ e.stopPropagation(); wrap.classList.toggle('open'); closeOthers(wrap); };
    pan.addEventListener('click', function(){ setTimeout(syncMenuLabels, 30); });
    pan.addEventListener('change', function(){ setTimeout(syncMenuLabels, 30); });
  });
  extra.forEach(function(e){
    /* спойлер «Больше фильтров» опустел — его группы уехали в меню */
    if(e.classList.contains('rf-more') && !e.querySelector('.chipf')) return;
    bar.appendChild(e);
  });
  try{ buildRentPriceMenu(bar); }catch(e){}
  try{ compactFilters('rentFilters'); filterSheet('rentFilters'); }catch(e){}
  wireCloseOnOutside();
  syncMenuLabels();
}

/* Бюджет аренды: та же кнопка-меню и тот же бегунок, что в продаже, плюс выбор
   срока — за ночь или в месяц. Единицы не смешиваем: ночную ставку нельзя
   умножить на 30 и выдать за месячную. */
function buildRentPriceMenu(bar){
  if(!bar || bar.querySelector('.fmenu[data-facet="rentbudget"]')) return;
  var haveNight=rentUnitAvailable('night'), haveMonth=rentUnitAvailable('month');
  if(!haveNight && !haveMonth) return;              /* ставок нет вообще — меню не рисуем */
  if(!haveNight) rentUnit='month'; else if(!haveMonth) rentUnit='night';

  var wrap=document.createElement('div'); wrap.className='fmenu'; wrap.dataset.facet='rentbudget';
  var btn=document.createElement('button'); btn.type='button'; btn.className='fbtn';
  btn.innerHTML='<span class="fb-t">'+t('rent.f.budget')+'</span><span class="fb-v"></span><i>▾</i>';
  var pan=document.createElement('div'); pan.className='fpan';
  wrap.appendChild(btn); wrap.appendChild(pan);
  bar.insertBefore(wrap, bar.firstChild);           /* бюджет первым, как в продаже */
  btn.onclick=function(e){ e.stopPropagation(); wrap.classList.toggle('open'); closeOthers(wrap); };

  var units=document.createElement('div'); units.className='rf-chips runits';
  [['night',t('u.night'),haveNight],['month',t('u.month'),haveMonth]].forEach(function(u){
    if(!u[2]) return;
    var c=document.createElement('span');
    c.className='chipf'+(rentUnit===u[0]?' on':''); c.textContent=u[1];
    c.onclick=function(){
      rentUnit=u[0]; rentPriceRange=null;
      Array.prototype.forEach.call(units.children,function(x){ x.classList.toggle('on', x===c); });
      drawSlider(); applyRentFilters(); syncMenuLabels();
    };
    units.appendChild(c);
  });
  if(units.children.length>1) pan.appendChild(units);

  var host=document.createElement('div'); pan.appendChild(host);
  drawSlider();

  function drawSlider(){
    host.innerHTML='';
    var vals=[];
    (PL.RENTALS||[]).forEach(function(p){
      var a=rentRate(p,rentUnit), b=rentRateTop(p,rentUnit);
      if(a) vals.push(a);
      if(b) vals.push(b);
    });
    if(!vals.length){ host.innerHTML='<p class="sub" style="margin:6px 2px">'+t('u.onreq')+'</p>'; return; }
    var step=(rentUnit==='month')?10000:1000;
    var lo=Math.floor(Math.min.apply(null,vals)/step)*step;
    /* Эльнур 06.09: «за сутки только до 28к — а если 50к?». Верхняя граница
       шла ровно по нашим четырём объектам, и шкала выглядела как весь рынок.
       Держим потолок по рынку Пхукета, а крайнее правое положение ручки
       означает «без верхней границы» — новые дорогие объекты не отсекаются. */
    var floorHi=(rentUnit==='month')?400000:80000;
    var hi=Math.ceil(Math.max(Math.max.apply(null,vals), floorHi)/step)*step;
    if(hi<=lo) hi=lo+step*5;
    var box=document.createElement('div'); box.className='prng';
    box.innerHTML=
      '<div class="prng-val"><span class="rp-out">'+t('f.any')+'</span>'+
        '<button type="button" class="prng-clr rp-clr">'+t('f.reset')+'</button></div>'+
      '<div class="prng-track rp-track">'+
        '<div class="prng-fill rp-fill"></div>'+
        '<button type="button" class="prng-h rp-a" aria-label="'+t('u.from')+'"></button>'+
        '<button type="button" class="prng-h rp-b" aria-label="'+t('u.from')+'"></button>'+
      '</div>'+
      '<div class="prng-ends"><span>'+fmtBaht(lo)+'</span><span>'+t('rent.f.nolimit')+'</span></div>';
    host.appendChild(box);

    var track=box.querySelector('.rp-track'), fill=box.querySelector('.rp-fill'),
        hA=box.querySelector('.rp-a'), hB=box.querySelector('.rp-b'), out=box.querySelector('.rp-out');
    var A=lo, B=hi;
    function pct(v){ return (v-lo)/(hi-lo)*100; }
    function draw(){
      var x=Math.min(A,B), y=Math.max(A,B);
      fill.style.left=pct(x)+'%'; fill.style.right=(100-pct(y))+'%';
      hA.style.left=pct(A)+'%'; hB.style.left=pct(B)+'%';
      var full=(x===lo && y===hi);
      out.textContent = full ? t('f.any')
        : (fmtBaht(x)+' — '+(y>=hi ? fmtBaht(hi)+'+' : fmtBaht(y)));
      return full;
    }
    function paint(){
      var full=draw(), x=Math.min(A,B), y=Math.max(A,B);
      rentPriceRange = full ? null : {from:x, to:(y>=hi ? Infinity : y)};
      applyRentFilters(); syncMenuLabels();
    }
    var drag=null;
    function valueAt(clientX){
      var r=track.getBoundingClientRect(); if(!r.width) return A;
      var k=(clientX-r.left)/r.width;
      return Math.round((lo + Math.max(0,Math.min(1,k))*(hi-lo))/step)*step;
    }
    function grab(e){
      var v=valueAt(e.clientX);
      drag=(Math.abs(v-A)===Math.abs(v-B)) ? (v<A?'a':'b') : (Math.abs(v-A)<Math.abs(v-B)?'a':'b');
      move(e);
      try{ track.setPointerCapture(e.pointerId); }catch(err){}
      wrap.classList.add('hold','open');
      e.preventDefault();
    }
    function move(e){ if(!drag) return; var v=valueAt(e.clientX); if(drag==='a') A=v; else B=v; paint(); }
    function drop(e){
      if(!drag) return; drag=null;
      try{ track.releasePointerCapture(e.pointerId); }catch(err){}
      setTimeout(function(){ wrap.classList.remove('hold'); },60);
    }
    track.addEventListener('pointerdown',grab);
    track.addEventListener('pointermove',move);
    track.addEventListener('pointerup',drop);
    track.addEventListener('pointercancel',drop);
    track.addEventListener('click',function(e){ e.stopPropagation(); });
    [hA,hB].forEach(function(h,i){
      h.addEventListener('keydown',function(e){
        var d=(e.key==='ArrowLeft')?-step:(e.key==='ArrowRight')?step:0;
        if(!d) return;
        if(i===0) A=Math.max(lo,Math.min(hi,A+d)); else B=Math.max(lo,Math.min(hi,B+d));
        paint(); e.preventDefault();
      });
    });
    box.querySelector('.rp-clr').onclick=function(e){
      e.stopPropagation(); A=lo; B=hi; paint();
    };
    draw();
  }
}

function buildFilterMenus(barId){
  var bar=document.getElementById(barId);
  if(!bar || bar.dataset.grouped) return;
  var chips=Array.prototype.slice.call(bar.querySelectorAll('.chipf'));
  if(!chips.length) return;
  var byFacet={};
  chips.forEach(function(c){ (byFacet[c.dataset.facet]=byFacet[c.dataset.facet]||[]).push(c); });

  bar.innerHTML=''; bar.dataset.grouped='1'; bar.classList.add('fbar-menus');
  FILTER_MENUS.forEach(function(m){
    var own=byFacet[m.key]||[];
    if(!own.length && !m.extra) return;
    var wrap=document.createElement('div'); wrap.className='fmenu'; wrap.dataset.facet=m.key;
    var btn=document.createElement('button');
    btn.type='button'; btn.className='fbtn';
    btn.innerHTML='<span class="fb-t">'+m.label+'</span><span class="fb-v"></span><i>▾</i>';
    var pan=document.createElement('div'); pan.className='fpan';
    own.forEach(function(c){ pan.appendChild(c); });
    if(m.extra) m.extra.forEach(function(x){
      /* чип уже вернулся из прошлой сборки — второй раз не создаём */
      if(own.some(function(o){ return o.dataset.val===x.v; })) return;
      var c=document.createElement('span');
      c.className='chipf'; c.dataset.facet=m.key; c.dataset.val=x.v; c.textContent=x.t;
      c.onclick=function(){ toggleFilter(c); };
      pan.appendChild(c);
    });
    wrap.appendChild(btn); wrap.appendChild(pan); bar.appendChild(wrap);
    btn.onclick=function(e){ e.stopPropagation(); wrap.classList.toggle('open'); closeOthers(wrap); };
  });
  try{ buildPriceSlider(bar); }catch(e){}
  try{ compactFilters(barId); filterSheet(barId); }catch(e){}
  try{ syncBudgetLabels(); }catch(e){}
  var reset=document.createElement('button');
  reset.type='button'; reset.className='fbtn fbtn-reset'; reset.textContent='Сбросить';
  reset.onclick=function(){ resetAllFilters(barId); };
  bar.appendChild(reset);
  wireCloseOnOutside();
  syncMenuLabels();
}
/* один общий слушатель на документ — панель пересобирается при каждом рендере,
   и без этого флага слушатели копились бы с каждым разом */
var closeWired=false;
function wireCloseOnOutside(){
  if(closeWired) return; closeWired=true;
  document.addEventListener('click', function(e){
    /* клик внутри раскрытой панели — это работа с фильтром, а не выход из неё.
       Без этого бегунок цены закрывал панель на первом же нажатии. */
    if(e.target.closest && e.target.closest('.fpan')) return;
    closeOthers(null);
  });
}
/* Бегунок цены. Эльнур 05.09: ступени оставляем — по ним удобно попасть сразу,
   а кто хочет точнее, тот докручивает ручками. Ступень и бегунок связаны:
   нажал ступень — ручки встали, подвинул ручки — ступень погасла. */
var priceRange=null; /* {from,to} в батах, null = без ограничения */
function buildPriceSlider(bar){
  var wrap=bar.querySelector('.fmenu[data-facet="budget"] .fpan');
  if(!wrap || wrap.querySelector('.prng')) return;
  var vals=(PL.PROPERTIES||[]).map(thbOf).filter(function(v){return v>0;});
  if(!vals.length) return;
  var lo=Math.floor(Math.min.apply(null,vals)/1e6), hi=Math.ceil(Math.max.apply(null,vals)/1e6);
  /* Эльнур 05.09: «до 45 млн мало, можно до 100+». Шкала тянется до 100 млн,
     верхняя ручка на краю значит «и дороже» — дорогие объекты не отсекаются. */
  hi=Math.max(hi,100);
  if(hi<=lo) hi=lo+1;

  /* Эльнур 05.09: «бегунки должны передвигаться». Два наложенных input[type=range]
     ловили нажатие через раз — ручка под ручкой, а по самой полосе клик вообще
     не проходил. Здесь свои ручки на pointer-событиях: тянутся мышью и пальцем,
     нажатие по полосе подводит ближайшую ручку, стрелки двигают с клавиатуры. */
  var box=document.createElement('div');
  box.className='prng';
  box.innerHTML=
    '<div class="prng-val"><span id="prngOut">'+t('f.any')+'</span>'+
      '<button type="button" class="prng-clr" id="prngClr">'+t('f.reset')+'</button></div>'+
    '<div class="prng-track" id="prngTrack">'+
      '<div class="prng-fill" id="prngFill"></div>'+
      '<button type="button" class="prng-h" id="prngA" aria-label="Цена от"></button>'+
      '<button type="button" class="prng-h" id="prngB" aria-label="Цена до"></button>'+
    '</div>'+
    '<div class="prng-ends"><span>'+fmtBaht(lo*1e6)+'</span><span>'+fmtBaht(hi*1e6)+'</span></div>';
  wrap.insertBefore(box, wrap.firstChild);

  var track=box.querySelector('#prngTrack'), fill=box.querySelector('#prngFill'),
      hA=box.querySelector('#prngA'), hB=box.querySelector('#prngB'),
      out=box.querySelector('#prngOut');
  var A=lo, B=hi;

  function pct(v){ return (v-lo)/(hi-lo)*100; }
  function draw(){
    var x=Math.min(A,B), y=Math.max(A,B);
    fill.style.left=pct(x)+'%'; fill.style.right=(100-pct(y))+'%';
    hA.style.left=pct(A)+'%'; hB.style.left=pct(B)+'%';
    var full=(x===lo && y===hi);
    out.textContent = full ? t('f.any')
      : (fmtBaht(x*1e6)+' — '+(y>=hi ? fmtBaht(hi*1e6)+'+' : fmtBaht(y*1e6)));
    return full;
  }
  function paint(){
    var full=draw();
    var x=Math.min(A,B), y=Math.max(A,B);
    priceRange = full ? null : {from:x*1e6, to:(y>=hi ? Infinity : y*1e6)};
    /* ручной диапазон отменяет выбранную ступень — иначе они спорят */
    if(!full){ activeFilter.budget='';
      bar.querySelectorAll('[data-facet="budget"].chipf').forEach(function(c){c.classList.remove('on');}); }
    applyFilters(); if(typeof syncMenuLabels==='function') syncMenuLabels();
  }

  var drag=null;
  function valueAt(clientX){
    var r=track.getBoundingClientRect();
    if(!r.width) return A;
    var k=(clientX-r.left)/r.width;
    return Math.round(lo + Math.max(0,Math.min(1,k))*(hi-lo));
  }
  function grab(e){
    var v=valueAt(e.clientX);
    /* ближняя ручка; если обе в одной точке — решаем по стороне нажатия */
    drag = (Math.abs(v-A)===Math.abs(v-B)) ? (v<A?'a':'b')
                                           : (Math.abs(v-A)<Math.abs(v-B)?'a':'b');
    move(e);
    try{ track.setPointerCapture(e.pointerId); }catch(err){}
    var menu=box.closest('.fmenu');
    if(menu) menu.classList.add('hold','open');
    e.preventDefault();
  }
  function move(e){
    if(!drag) return;
    var v=valueAt(e.clientX);
    if(drag==='a') A=v; else B=v;
    paint();
  }
  function drop(e){
    if(!drag) return;
    drag=null;
    try{ track.releasePointerCapture(e.pointerId); }catch(err){}
    var menu=box.closest('.fmenu');
    if(menu) menu.classList.remove('hold');
  }
  track.addEventListener('pointerdown', grab);
  track.addEventListener('pointermove', move);
  track.addEventListener('pointerup', drop);
  track.addEventListener('pointercancel', drop);
  /* панель фильтра закрывается по клику вне — нажатие на бегунок к ней не относится */
  track.addEventListener('click', function(e){ e.stopPropagation(); });

  [[hA,'a'],[hB,'b']].forEach(function(pair){
    pair[0].addEventListener('keydown', function(e){
      var d = (e.key==='ArrowRight'||e.key==='ArrowUp') ? 1
            : (e.key==='ArrowLeft'||e.key==='ArrowDown') ? -1 : 0;
      if(!d) return;
      e.preventDefault();
      if(pair[1]==='a') A=Math.max(lo,Math.min(hi,A+d)); else B=Math.max(lo,Math.min(hi,B+d));
      paint();
    });
  });

  /* даём внешнему коду перерисовать подписи бегунка при смене валюты */
  window.syncPriceSlider=function(){
    var ends=box.querySelectorAll('.prng-ends span');
    if(ends.length===2){ ends[0].textContent=fmtBaht(lo*1e6); ends[1].textContent=fmtBaht(hi*1e6); }
    draw();
  };
  box.querySelector('#prngClr').onclick=function(e){
    e.stopPropagation(); A=lo; B=hi; paint();
  };
  /* нажали ступень — двигаем ручки к её границам */
  bar.querySelectorAll('.fmenu[data-facet="budget"] .chipf').forEach(function(c){
    c.addEventListener('click',function(){
      var G={'':[lo,hi],b1:[lo,5],b2:[5,10],b3:[10,15],b4:[15,20],b5:[20,25],b6:[25,30],b7:[30,hi]};
      var r=G[c.dataset.val]||[lo,hi];
      A=Math.max(lo,r[0]); B=Math.min(hi,r[1]);
      draw();
      if(c.dataset.val==='') out.textContent=t('f.any');
      priceRange=null; /* ступень фильтрует сама, диапазон не дублируем */
    },true);
  });
  draw();
}
function closeOthers(keep){
  document.querySelectorAll('.fmenu.open').forEach(function(w){ if(w!==keep) w.classList.remove('open'); });
}
/* на кнопке показываем, что выбрано — иначе выбор не виден, когда список закрыт */
function syncMenuLabels(){
  /* активные фильтры подсвечивают кнопку сброса на телефоне */
  ['saleFilters','rentFilters'].forEach(function(id){
    var b=document.getElementById(id); if(!b) return;
    var active = b.querySelectorAll('.fmenu.has').length>0;
    b.classList.toggle('has-active', active);
    try{ updateFilterCount(id); }catch(e){}
  });
  document.querySelectorAll('.fmenu').forEach(function(w){
    var f=w.dataset.facet, out=[];
    /* бюджет аренды: на кнопке показываем сам диапазон, а не выбранный срок */
    if(f==='rentbudget'){
      var v0=w.querySelector('.fb-v');
      var o=w.querySelector('.rp-out');
      var txt=(rentPriceRange && o) ? (o.textContent+' '+t(rentUnit==='month'?'u.month':'u.night')) : '';
      if(v0) v0.textContent=txt;
      w.classList.toggle('has', !!txt);
      return;
    }
    w.querySelectorAll('.chipf.on').forEach(function(c){
      if(f==='budget' && c.dataset.val==='') return;
      out.push(c.textContent.trim());
    });
    /* удобства аренды — чекбоксы, а не чипы: их выбор тоже показываем на кнопке */
    w.querySelectorAll('.rf-check input:checked').forEach(function(i){
      var lab=i.parentNode.querySelector('span');
      out.push(lab?lab.textContent.trim():'✓');
    });
    var v=w.querySelector('.fb-v');
    v.textContent = out.length ? (out.length>2 ? out.length+' выбрано' : out.join(', ')) : '';
    w.classList.toggle('has', out.length>0);
  });
}
function resetAllFilters(barId){
  priceRange=null;
  var _c=document.getElementById('prngClr'); if(_c) _c.click();
  activeFilter.budget=''; activeFilter.loc.clear(); activeFilter.type.clear();
  activeFilter.stage.clear(); activeFilter.beds.clear();
  document.querySelectorAll('#'+barId+' .chipf').forEach(function(c){
    c.classList.toggle('on', c.dataset.facet==='budget' && c.dataset.val==='');
  });
  applyFilters(); syncMenuLabels();
}

function toggleFilter(chip){
  var f=chip.dataset.facet,v=chip.dataset.val;
  if(f==='budget'){activeFilter.budget=v;document.querySelectorAll('#saleFilters [data-facet="budget"]').forEach(function(c){c.classList.toggle('on',c===chip);});}
  else{var set=activeFilter[f];if(set.has(v)){set.delete(v);chip.classList.remove('on');}else{set.add(v);chip.classList.add('on');}}
  applyFilters();
  if(typeof syncMenuLabels==='function') syncMenuLabels();
}
function applyFilters(){
  var shown=0,q=(saleQuery||'').trim().toLowerCase();
  document.querySelectorAll('#saleCar .prop').forEach(function(pEl){
    var okB=!activeFilter.budget||pEl.dataset.budget===activeFilter.budget;
    /* точный диапазон с бегунка — поверх ступеней */
    if(okB && priceRange){
      var _p=+pEl.dataset.thb||0;
      okB = _p>=priceRange.from && _p<=priceRange.to;
    }
    var okL=activeFilter.loc.size===0||activeFilter.loc.has(pEl.dataset.loc);
    var okT=activeFilter.type.size===0||activeFilter.type.has(pEl.dataset.type);
    var _st=(pEl.dataset.stage||'').split(' ');
    var okS=activeFilter.stage.size===0||_st.some(function(x){return activeFilter.stage.has(x);});
    /* спальни: объект подходит, если запрошенное число попадает в его диапазон */
    var okBd=true;
    if(activeFilter.beds.size){
      var lo=parseInt(pEl.dataset.bmin,10), hi=parseInt(pEl.dataset.bmax,10);
      if(isNaN(lo)&&isNaN(hi)) okBd=false;
      else{
        if(isNaN(lo)) lo=hi; if(isNaN(hi)) hi=lo;
        okBd=false;
        activeFilter.beds.forEach(function(v){
          var n=parseInt(v,10);
          if(v==='4'){ if(hi>=4) okBd=true; }
          else if(n>=lo && n<=hi) okBd=true;
        });
      }
    }
    var okF=!favOnly||FAVS.has(pEl.dataset.pid);
    var okQ=!q||pEl.textContent.toLowerCase().indexOf(q)>-1;
    var vis=okB&&okL&&okT&&okQ&&okF&&okS&&okBd;
    pEl.style.display=vis?'':'none';if(vis)shown++;
  });
  if(top7Only) shown=applyTop7();
  var nr=document.getElementById('saleNoResult');if(nr)nr.style.display=shown?'none':'block';
  var sf=document.getElementById('saleFound');
  if(sf) sf.textContent = shown + ' ' + (PL.lang==='en' ? (shown===1?'property':'properties')
        : plural(shown,'объект','объекта','объектов')) + ' ' +
    (top7Only ? (hotList().length ? t('f.hotnote') : t('f.top7note')) : t('f.found'));
  /* страницам каталога нужно обновить счётчик и карту после фильтрации */
  if(typeof window.PLP_AFTER_FILTER==='function') window.PLP_AFTER_FILTER(shown);
}
function onSaleSearch(v){saleQuery=v;applyFilters();}
/* Эльнур 05.09: «топ-7 — это самые горячие офферы, то что мы продаём».
   Витрину задаём руками: в базе у объекта поле hot_rank (1..7 — порядок).
   Пока ни один объект не отмечен, показываем семь самых доходных и честно
   подписываем — чтобы пункт не был пустым. */
var top7Only=false;
function hotList(){
  return (PL.PROPERTIES||[]).filter(function(p){ return p.hot!=null; })
    .sort(function(a,b){ return a.hot-b.hot; });
}
function applyTop7(){
  var car=document.getElementById('saleCar'); if(!car) return 0;
  var vis=Array.prototype.slice.call(car.querySelectorAll('.prop'))
    .filter(function(el){ return el.style.display!=='none'; });
  if(!top7Only) return vis.length;
  var hot=hotList();
  if(hot.length){
    var rank={}; hot.forEach(function(p,i){ rank[p.property_id]=i; });
    vis.forEach(function(el){ if(!(el.dataset.pid in rank)) el.style.display='none'; });
    var keep=vis.filter(function(el){ return el.dataset.pid in rank; })
                .sort(function(a,b){ return rank[a.dataset.pid]-rank[b.dataset.pid]; });
    keep.forEach(function(el,i){ if(i>=7) el.style.display='none'; else car.appendChild(el); });
    return Math.min(keep.length,7);
  }
  vis.sort(function(a,b){
    var pa=PL.byId[a.dataset.pid]||{}, pb=PL.byId[b.dataset.pid]||{};
    return (pb.roi||0)-(pa.roi||0);
  });
  vis.forEach(function(el,i){ if(i>=7) el.style.display='none'; });
  return Math.min(vis.length,7);
}
function setSaleSort(v){
  var car=document.getElementById('saleCar');if(!car)return;
  top7Only=(v==='top7');
  if(top7Only) v='roi';   /* внутри — та же сортировка по доходности */
  var els=Array.prototype.slice.call(car.querySelectorAll('.prop'));
  function val(el){var p=PL.byId[el.dataset.pid];if(!p)return 0;return v==='roi'?(p.roi||0):v==='price'?p.priceUSD:v==='price-desc'?-p.priceUSD:0;}
  if(v)els.sort(function(a,b){return v==='roi'?val(b)-val(a):val(a)-val(b);});
  else els.sort(function(a,b){
    return PL.PROPERTIES.findIndex(function(p){return p.property_id===a.dataset.pid;})-PL.PROPERTIES.findIndex(function(p){return p.property_id===b.dataset.pid;});
  });
  els.forEach(function(el){car.appendChild(el);});
  applyFilters();   /* режим топ-7 включается и выключается вместе с сортировкой */
}

/* Поиск и сортировка аренды — зеркало продажи. Сортируем по спальням и
   площади: цены в аренде нет, сортировать по ней нечего. */
var rentQuery='';
function onRentSearch(v){ rentQuery=v; applyRentFilters(); }
function rentNum(x){ var m=String(x==null?'':x).match(/\d+([.,]\d+)?/g); return m?parseFloat(m[m.length-1].replace(',','.')):0; }
function setRentSort(v){
  var car=document.getElementById('rentCar'); if(!car) return;
  var els=Array.prototype.slice.call(car.querySelectorAll('.prop'));
  function val(el){
    var p=PL.byId[el.dataset.pid]; if(!p) return 0;
    return v==='beds' ? (p.bmax!=null?p.bmax:rentNum(p.beds)) : v==='area' ? rentNum(p.area) : 0;
  }
  if(v) els.sort(function(a,b){ return val(b)-val(a); });
  else els.sort(function(a,b){
    return PL.RENTALS.findIndex(function(p){return p.property_id===a.dataset.pid;})-
           PL.RENTALS.findIndex(function(p){return p.property_id===b.dataset.pid;});
  });
  els.forEach(function(el){ car.appendChild(el); });
}

/* Переключатель оформления. По кругу: как в системе → светлое → тёмное.
   Выбор запоминается в этом браузере. */
var THEMES=['system','light','dark'];
function themeNow(){
  try{ var v=localStorage.getItem('pl_theme'); if(v==='dark'||v==='light') return v; }catch(e){}
  return 'system';
}
function paintThemeBtn(){
  var ico=document.getElementById('themeIco'), b=document.getElementById('themeBtn');
  var v=themeNow();
  var sym = v==='light' ? '☀' : v==='dark' ? '☾' : '◐';
  /* тот же значок в бургере — на телефоне переключатель живёт там */
  var mIco=document.getElementById('mThemeIco'); if(mIco) mIco.textContent=sym;
  if(!ico||!b) return;
  ico.textContent = sym;
  b.title = v==='light' ? 'Светлое оформление' : v==='dark' ? 'Тёмное оформление' : 'Как в системе';
  /* 🔴 17.09 Эльнур: «сам лого сейчас на тёмной теме — бежевый фон, белые буквы,
     может лучше чёрные буквы?». Правило «на тёмном фоне берём светлый знак» здесь
     не работает: подложка знака — фирменный оливковый #D2D5B3, он ОДИН на обе темы
     (объявлен в :root и нигде не переопределяется). Значит на тёмной теме белый знак
     ложился на светло-бежевое. Знак на подложке всегда чернильный; светлая версия
     остаётся для мест, где логотип лежит прямо на тёмном фоне, без подложки. */
  document.querySelectorAll('.logo .chip img').forEach(function(img){
    var pre = (img.getAttribute('src')||'').indexOf('../')===0 ? '../' : '';
    var want = pre + 'img/brand/plp-mark-ink.png';
    if(img.getAttribute('src')!==want) img.setAttribute('src',want);
  });
}
function setTheme(v){
  try{
    if(v==='system') localStorage.removeItem('pl_theme');
    else localStorage.setItem('pl_theme',v);
  }catch(e){}
  if(v==='system') document.documentElement.removeAttribute('data-theme');
  else document.documentElement.setAttribute('data-theme',v);
  if(window.paintChrome) window.paintChrome();
  paintThemeBtn();
}
function cycleTheme(){
  var i=THEMES.indexOf(themeNow());
  setTheme(THEMES[(i+1)%THEMES.length]);
}

/* ===== FAVOURITES / COMPARE ===== */
var FAVS=new Set(),CMP=new Set();
try{FAVS=new Set(JSON.parse(localStorage.getItem('pl_favs')||'[]'));}catch(e){}
function saveFavs(){try{localStorage.setItem('pl_favs',JSON.stringify(Array.from(FAVS)));}catch(e){}}
function toggleFav(pid){
  if(FAVS.has(pid))FAVS.delete(pid);else FAVS.add(pid);
  saveFavs();syncCardStates();updateTray();
  if(favOnly){ applyFilters(); try{ applyRentFilters(); }catch(e){} }
}
function toggleCmp(pid){
  if(CMP.has(pid))CMP.delete(pid);
  else{if(CMP.size>=3){flashTray(t('cmp.max'));return;}CMP.add(pid);}
  syncCardStates();updateTray();
}
function syncCardStates(){
  /* 07.09: обновлялись только карточки в двух каруселях главной, поэтому
     в каталоге и на страницах разделов кнопки «в избранное» и «сравнить»
     нажимались, но вид не менялся — выглядело как мёртвая кнопка. */
  document.querySelectorAll('.prop').forEach(function(el){
    var pid=el.dataset.pid;
    var f=el.querySelector('.fav'),c=el.querySelector('.cmpb');
    if(f){var on=FAVS.has(pid);f.classList.toggle('on',on);f.textContent=on?'♥':'♡';}
    if(c){var on2=CMP.has(pid);c.classList.toggle('on',on2);c.textContent=on2?t('u.cmpOn'):t('u.cmp');}
  });
}
function flashTray(msg){
  var tr=document.getElementById('tray');if(!tr)return;
  tr.classList.add('open');
  var n=tr.querySelector('.tmsg');if(n){n.textContent=msg;n.classList.add('show');setTimeout(function(){n.classList.remove('show');updateTray();},2200);}
}
function updateTray(){
  var tr=document.getElementById('tray');if(!tr)return;
  var nF=FAVS.size,nC=CMP.size;
  tr.classList.toggle('open',nF>0||nC>0);
  var fb=tr.querySelector('.t-fav'),cb2=tr.querySelector('.t-cmp');
  if(fb){fb.style.display=nF?'':'none';fb.querySelector('b').textContent=nF;var sp=fb.querySelector('span');if(sp)sp.textContent=t('tray.fav');}
  if(cb2){cb2.style.display=nC>1?'':'none';cb2.querySelector('b').textContent=nC;var sp2=cb2.querySelector('span');if(sp2)sp2.textContent=t('tray.cmp');}
  ['favChip','rentFavChip'].forEach(function(id){
    var fc=document.getElementById(id); if(fc) fc.style.display=nF?'':'none';
  });
}
function toggleFavOnly(){
  favOnly=!favOnly;
  ['favChip','rentFavChip'].forEach(function(id){
    var fc=document.getElementById(id); if(fc) fc.classList.toggle('on',favOnly);
  });
  applyFilters();
  try{ applyRentFilters(); }catch(e){}
}
function openCompare(){
  if(CMP.size<2){flashTray(t('cmp.need2'));return;}
  var items=Array.from(CMP).map(function(id){return PL.byId[id];}).filter(Boolean);
  var m=document.getElementById('cmpModal');
  var rows=[
    [t('cmp.r.loc'),function(p){return loc(p.loc);}],
    [t('cmp.r.type'),function(p){return loc(p.type);}],
    /* в сравнение попадает и аренда: там нет цены, доходности и срока сдачи —
       пишем «по запросу» и прочерки вместо ฿0 и пустых клеток */
    [t('cmp.r.price'),function(p){return p.funnel==='rent'?rentPriceShort(p):fmtBaht(thbOf(p));}],
    ['ROI',function(p){return p.roi!=null?roiRange(p):'—';}],
    [t('cmp.r.area'),function(p){return areaOf(p)||'—';}],
    [t('cmp.r.beds'),function(p){return p.beds||'—';}],
    [t('cmp.r.deadline'),function(p){return loc(p.deadline)||'—';}],
    [t('cmp.r.status'),function(p){return p.status?t('st.'+p.status):'—';}]
  ];
  var best=Math.max.apply(null,items.map(function(p){return p.roi||0;}));
  m.querySelector('.cmp-body').innerHTML=
    '<div class="cmp-grid" style="grid-template-columns:110px repeat('+items.length+',minmax(0,1fr))">'+
    '<div class="ch"></div>'+items.map(function(p){return '<div class="ch">'+thumbDiv(p)+'<b>'+p.title+'</b><span class="pid">'+p.property_id+'</span></div>';}).join('')+
    rows.map(function(r){
      return '<div class="ck">'+r[0]+'</div>'+items.map(function(p){
        var isRoi=r[0]==='ROI',win=isRoi&&p.roi!=null&&p.roi===best&&items.length>1;
        return '<div class="cv'+(win?' win':'')+'">'+r[1](p)+(win?'<span class="wb">'+t('cmp.win')+'</span>':'')+'</div>';
      }).join('');
    }).join('')+'</div>';
  m.classList.add('open');document.body.style.overflow='hidden';
}
function closeCompare(){document.getElementById('cmpModal').classList.remove('open');document.body.style.overflow='';}
function cmpLead(){var ids=Array.from(CMP).join(', ');closeCompare();pushLead({funnel:'sale',goal:'compare',note:ids});openChat('compare');setTimeout(function(){offerLead(true);},600);}
function favLead(){var ids=Array.from(FAVS).join(', ');pushLead({funnel:'sale',goal:'shortlist',note:ids});openChat('shortlist');setTimeout(function(){offerLead(true);},600);}

/* ===== QUIZ (8 шагов → лид) ===== */
var QUIZ_STEPS=[
  {key:'goal',q:'q.1',opts:['q.1a','q.1b','q.1c','q.1d'],vals:['invest','live','rent','explore']},
  {key:'budget',q:'q.2',opts:['q.2a','q.2b','q.2c','q.2e','q.2f','q.2d'],vals:['b1','b2','b3','b4','b56','rent']},
  {key:'area',q:'q.3',opts:['q.3a','q.3b','q.3c','q.3d','q.3e','q.3f','q.3g','q.3h']},
  {key:'type',q:'q.4',opts:['q.4a','q.4b','q.4c','q.4d'],vals:['Кондо','Вилла','Таунхаус','']},
  {key:'beds',q:'q.5',opts:['q.5a','q.5b','q.5c','q.5d']},
  {key:'timing',q:'q.6',opts:['q.6a','q.6b','q.6c','q.6d']},
  {key:'channel',q:'q.7',opts:['q.7a','q.7b','q.7c','q.7d']},
  {key:'contact',q:'q.8',form:true}
];
var qzIdx=0,qzAns={},qzRenderedAt=0;
function openQuiz(){qzIdx=0;qzAns={};document.getElementById('quizModal').classList.add('open');document.body.style.overflow='hidden';renderQuiz();}
function closeQuiz(){document.getElementById('quizModal').classList.remove('open');document.body.style.overflow='';}
function quizMatch(){
  var b=qzAns.budget,ty=qzAns.type;
  if(b==='rent'||qzAns.goal==='rent')return PL.RENTALS[0]||PL.PROPERTIES[0];
  var pool=PL.PROPERTIES.filter(function(p){return p.status!=='sold';});
  /* в формах ступени сведены крупнее, чем в фильтре: b4 = 15–25, b56 = 25+ */
  var GROUP={b4:['b4','b5'],b56:['b6','b7']};
  if(b){var want=GROUP[b]||[b];
    var pb=pool.filter(function(p){return want.indexOf(budgetOf(p))>=0;});
    if(pb.length)pool=pb;}
  if(ty){var pt=pool.filter(function(p){return p.type.ru===ty;});if(pt.length)pool=pt;}
  return pool[0]||PL.PROPERTIES[0];
}
function renderQuiz(){
  var step=QUIZ_STEPS[qzIdx];
  document.getElementById('qzStep').textContent=t('quiz.step')+' '+(qzIdx+1)+' '+t('quiz.of')+' '+QUIZ_STEPS.length;
  document.getElementById('qzBar').style.width=((qzIdx+1)/QUIZ_STEPS.length*100)+'%';
  var body=document.getElementById('qzBody'),foot=document.getElementById('qzFoot');
  if(step.form){
    var m=quizMatch();
    body.innerHTML='<div class="qz-q">'+t('q.8')+'</div>'+
      '<div class="qz-match">'+thumbDiv(m)+'<div><div class="k">'+t('quiz.match')+'</div><div class="v">'+(m.title||t('soon.t'))+' · '+loc(m.loc)+'</div><div class="pid">'+m.property_id+'</div></div></div>'+
      '<div class="qz-form"><input id="qzName" placeholder="'+t('q.8name')+'">'+
      '<input id="qzContact" type="tel" inputmode="tel" autocomplete="tel" placeholder="'+t('lf.phone')+'">'+
      '<select id="qzCh"><option value="whatsapp">WhatsApp</option><option value="telegram">Telegram</option></select>'+
      '<input id="qzTg" placeholder="'+t('lf.tg')+'">'+
      '<input class="hp" id="qzHp" tabindex="-1" autocomplete="off">'+
      '<label class="consent"><input type="checkbox" id="qzOk"><span>'+t('q.8consent')+'</span></label></div>';
    foot.innerHTML='<button type="button" class="qz-back" onclick="quizBack()">'+t('quiz.back')+'</button><button type="button" class="qz-next" id="qzSend" disabled>'+t('q.8send')+'</button>';
    qzRenderedAt=Date.now();
    var okEl=document.getElementById('qzOk'),sendEl=document.getElementById('qzSend');
    /* 09.09: раньше хватало любых четырёх символов — проходило «связь на ватсап».
       Теперь кнопка ждёт настоящий номер с кодом страны. */
    var qcEl=document.getElementById('qzContact');
    function gate(){sendEl.disabled=!(okEl.checked&&!phoneProblem(qcEl.value));}
    okEl.onchange=gate;
    qcEl.addEventListener('input',function(){ markBadContact(qcEl,''); gate(); });
    sendEl.onclick=submitQuiz;
  }else{
    body.innerHTML='<div class="qz-q">'+t(step.q)+'</div><div class="qz-opts">'+
      step.opts.map(function(o,i){
        var val=step.vals?step.vals[i]:'';
        var stored=step.vals?val:t(o);
        var on=qzAns[step.key]===stored||qzAns[step.key]===t(o)?' on':'';
        /* ступени бюджета подписываем в выбранной валюте — иначе фильтр говорит
           в долларах, а квиз в батах */
        var st=(step.key==='budget') ? BUDGET_STEPS.filter(function(x){return x.v===val;})[0] : null;
        var lab=st?budgetLabel(st):t(o);
        if(step.key==='budget'&&val==='b56') lab=fmtBaht(25e6)+'+';
        if(step.key==='budget'&&val==='b4')  lab=fmtBaht(15e6)+'–'+fmtBaht(25e6);
        return '<button type="button" class="qz-opt'+on+'" data-v="'+val+'" onclick="pickQuiz(\''+step.key+'\',\''+val.replace(/'/g,'')+'\',this)" data-label="'+lab+'">'+lab+'</button>';
      }).join('')+'</div>';
    foot.innerHTML=(qzIdx>0?('<button type="button" class="qz-back" onclick="quizBack()">'+t('quiz.back')+'</button>'):'')+
      '<button type="button" class="qz-next" id="qzNext" '+(qzAns[step.key]!=null?'':'disabled')+' onclick="quizNext()">'+t('quiz.next')+'</button>';
  }
}
function pickQuiz(key,val,el){
  var step=QUIZ_STEPS[qzIdx];
  qzAns[key]=step.vals?(val||el.dataset.label):el.dataset.label;
  el.parentNode.querySelectorAll('.qz-opt').forEach(function(b){b.classList.remove('on');});
  el.classList.add('on');
  var nx=document.getElementById('qzNext');if(nx)nx.disabled=false;
  var idx=qzIdx;
  setTimeout(function(){if(qzIdx===idx)quizNext();},180);
}
function quizNext(){if(qzIdx<QUIZ_STEPS.length-1){qzIdx++;renderQuiz();}}
function quizBack(){if(qzIdx>0){qzIdx--;renderQuiz();}}
function submitQuiz(){
  if(document.getElementById('qzHp').value.trim()){closeQuiz();return;}
  if(Date.now()-qzRenderedAt<1200)return;
  if(!document.getElementById('qzOk').checked)return;
  var cin=document.getElementById('qzContact'), prob=phoneProblem(cin.value);
  if(prob){ markBadContact(cin,prob); cin.focus(); return; }
  markBadContact(cin,'');
  var tgEl=document.getElementById('qzTg'), tprob=tgProblem(tgEl?tgEl.value:'');
  if(tprob){ markBadContact(tgEl,tprob); tgEl.focus(); return; }
  if(tgEl) markBadContact(tgEl,'');
  var qzSend=document.getElementById('qzSend');if(qzSend)qzSend.disabled=true; // анти-дубль пока идёт сеть
  var m=quizMatch();
  var lead=pushLead({
    funnel:(qzAns.budget==='rent'||qzAns.goal==='rent')?'rent':'sale',
    property_id:m.property_id,
    name:document.getElementById('qzName').value.trim(),
    contact:document.getElementById('qzContact').value.trim(),
    phone:document.getElementById('qzContact').value.trim(),
    tg_username:(document.getElementById('qzTg')||{value:''}).value.trim(),
    channel:(document.getElementById('qzCh')||{value:'whatsapp'}).value,
    consent:true,goal:qzAns.goal,budget:qzAns.budget,answers:qzAns
  });
  lead.__send.then(function(){
    document.getElementById('qzBody').innerHTML='<div class="qz-done"><div class="ic">✓</div><h3>'+t('quiz.done.t')+'</h3><p>'+t('quiz.done.p')+'</p>'+
      '<div class="qz-match" style="margin-top:18px">'+thumbDiv(m)+'<div><div class="k">'+t('quiz.match')+'</div><div class="v">'+(m.title||t('soon.t'))+' · '+loc(m.loc)+'</div><div class="pid">'+m.property_id+'</div></div></div></div>';
    document.getElementById('qzFoot').innerHTML='<button type="button" class="qz-back" onclick="closeQuiz()">'+t('quiz.done.close')+'</button>'+
      (m.soon?'':('<button type="button" class="qz-next" onclick="closeQuiz();openProp(\''+m.property_id+'\')">'+t('quiz.view')+'</button>'));
    document.getElementById('qzStep').textContent='';
    document.getElementById('qzBar').style.width='100%';
  }).catch(function(){
    document.getElementById('qzBody').innerHTML='<div class="qz-done"><div class="ic">!</div><h3>'+t('quiz.err.t')+'</h3><p>'+t('quiz.err.p')+'</p>'+
      '<div style="margin-top:18px"><a class="btn btn-green btn-block" href="https://t.me/elnurphuket_bot?start=quiz" target="_blank" rel="noopener">Открыть консьержа в Telegram</a></div></div>';
    document.getElementById('qzFoot').innerHTML='<button type="button" class="qz-back" onclick="closeQuiz()">'+t('quiz.done.close')+'</button>';
    if(qzSend)qzSend.disabled=false;
  });
}

/* ===== MAP + DISTRICTS ===== */
function distProps(nameRu){
  return PL.PROPERTIES.concat(PL.RENTALS.filter(function(p){return !p.soon;})).filter(function(p){return p.loc&&p.loc.ru===nameRu;});
}
function dName(d){return PL.lang==='en'?d.en:d.ru;}
function mapXY(d){
  var x=(d.lng-98.235)/0.21*300;
  var y=(8.205-d.lat)/0.47*560;
  return {x:x,y:y};
}
function renderMap(){
  var g=document.getElementById('mapMarkers');if(!g)return;
  var html='';
  PL.DISTRICTS.forEach(function(d,i){
    var pt=mapXY(d),n=distProps(d.ru).length;
    var lx=pt.x+(d.dx||14),ly=pt.y+(d.dy||0)+4;
    var anchor=(d.dx||14)<0?'end':'start';
    html+='<g class="dmk" data-d="'+i+'">'+
      '<circle cx="'+pt.x.toFixed(1)+'" cy="'+pt.y.toFixed(1)+'" r="'+(n?11:7)+'"'+(n?'':' opacity=".55"')+'></circle>'+
      (n?('<text class="cnt" x="'+pt.x.toFixed(1)+'" y="'+(pt.y+3.5).toFixed(1)+'" text-anchor="middle">'+n+'</text>'):'')+
      '<text x="'+lx.toFixed(1)+'" y="'+ly.toFixed(1)+'" text-anchor="'+anchor+'">'+dName(d)+'</text></g>';
  });
  g.innerHTML=html;
  g.querySelectorAll('.dmk').forEach(function(el){
    el.addEventListener('click',function(){openDistrict(PL.DISTRICTS[+el.dataset.d].ru);});
  });
}
/* у восьми районов есть свои страницы — карточка ведёт туда, остальные открываются окном */
var DPAGE={'Банг Тао':'bang-tao','Лаян':'layan','Сурин':'surin','Камала':'kamala',
           'Равай':'rawai','Раваи':'rawai','Ката':'kata','Най Янг':'nai-yang','Ко Кео':'koh-kaew'};
/* живая карта: метки стоят по координатам объектов из базы.
   Объекты без координат на карту не попадают — лучше пусто, чем ложная точка. */
var PLPMAP=null, PLPLAYER=null, PLPFILTER='all', PLPTILES=null, PLPVIEW='map', PLPMARKS={}, PLPFALLBACK=null;
function renderMapReal(){
  var box=document.getElementById('plpMap'); if(!box||!window.L) return;
  var all=[].concat(PL.PROPERTIES,PL.RENTALS).filter(function(p){return p.lat&&p.lng;});
  if(!all.length){ box.style.display='none'; return; }

  if(!PLPMAP){
    PLPMAP=L.map(box,{scrollWheelZoom:false,attributionControl:true,zoomControl:false})
      .setView([7.95,98.33],11);
    L.control.zoom({position:'topright'}).addTo(PLPMAP);
    /* Два слоя без ключа и без оплаты: обычная карта и снимки со спутника.
       CARTO пробовали — без API-ключа он штампует поверх «API KEY REQUIRED». */
    /* Векторный слой требует WebGL. Где его нет (старое железо, отключён в
       настройках), maplibre падает с ошибкой — и раньше вместе с ним ломалась
       вся настройка карты: кнопки «Продажа / Аренда» оставались без обработчиков.
       Теперь при сбое просто берём обычные тайлы. */
    function rasterLayer(){
      return L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{
        maxZoom:19, attribution:'© OpenStreetMap'});
    }
    function hasWebGL(){
      try{
        var c=document.createElement('canvas');
        return !!(window.WebGLRenderingContext &&
                  (c.getContext('webgl')||c.getContext('experimental-webgl')));
      }catch(e){ return false; }
    }
    function baseLayer(){
      if(window.L && L.maplibreGL && hasWebGL()){
        try{
          return L.maplibreGL({ style:'https://tiles.openfreemap.org/styles/liberty',
            attribution:'© OpenMapTiles, © OpenStreetMap' });
        }catch(e){}
      }
      return rasterLayer();
    }
    PLPTILES = {
      map: baseLayer(),
      sat: L.layerGroup([
        L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{
          maxZoom:19, attribution:'Esri, Maxar, Earthstar Geographics'}),
        /* поверх снимка — прозрачный слой с названиями дорог и пляжей */
        L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{
          maxZoom:19, opacity:.9})
      ])
    };
    try{ PLPTILES.map.addTo(PLPMAP); }
    catch(e){ PLPTILES.map = rasterLayer(); PLPTILES.map.addTo(PLPMAP); }
    /* Если векторный слой всё-таки сорвётся уже на ходу (так бывает, когда
       WebGL формально есть, но не работает), меняем его на растровый и
       перерисовываем — иначе карта остаётся без меток и без фильтров. */
    PLPFALLBACK=function(){
      if(PLPVIEW!=='map' || PLPTILES.__raster) return false;
      try{ PLPMAP.removeLayer(PLPTILES.map); }catch(e){}
      PLPTILES.map=rasterLayer(); PLPTILES.__raster=true;
      PLPTILES.map.addTo(PLPMAP);
      return true;
    };
    PLPMAP.attributionControl.setPrefix('');
    /* колесо прокручивает страницу, карта масштабируется по Ctrl или после клика —
       иначе карта перехватывает прокрутку и по ней невозможно проехать */
    PLPMAP.on('click', function(){ PLPMAP.scrollWheelZoom.enable(); });
    PLPMAP.on('mouseout', function(){ PLPMAP.scrollWheelZoom.disable(); });
    PLPMAP.on('zoomend', function(){
      safeDraw(true);
      var rb=document.getElementById('plpReset');
      if(rb) rb.style.display = PLPMAP.getZoom() > 11 ? '' : 'none';
    });
    var rb=document.getElementById('plpReset');
    if(rb) rb.onclick=function(){ resetMapView(); };

    var vb=document.getElementById('plpView');
    if(vb) Array.prototype.forEach.call(vb.querySelectorAll('button'),function(b){
      b.onclick=function(){
        Array.prototype.forEach.call(vb.querySelectorAll('button'),function(x){x.classList.remove('on');});
        b.classList.add('on');
        var v=b.getAttribute('data-v');
        if(v===PLPVIEW) return;
        PLPMAP.removeLayer(PLPTILES[PLPVIEW]); PLPVIEW=v; PLPTILES[v].addTo(PLPMAP);
        /* на снимке чёрные ценники теряются — делаем их светлыми */
        document.getElementById('plpMap').classList.toggle('on-sat', v==='sat');
      };
    });

    var fb=document.getElementById('plpFilt');
    if(fb) Array.prototype.forEach.call(fb.querySelectorAll('button'),function(b){
      b.onclick=function(){
        Array.prototype.forEach.call(fb.querySelectorAll('button'),function(x){x.classList.remove('on');});
        b.classList.add('on'); PLPFILTER=b.getAttribute('data-f'); safeDraw();
        /* список рядом с картой держим в том же наборе, что и метки */
        window.__mapFilter=PLPFILTER;
        try{ renderMapObjs(PLPFILTER); }catch(e){}
      };
    });
  }
  safeDraw();
  renderMapReal.__draw=safeDraw;

  /* один раз пробуем ещё, уже на растровых тайлах */
  function safeDraw(keepView){
    try{ drawPins(keepView); }
    catch(e){ if(PLPFALLBACK && PLPFALLBACK()) { try{ drawPins(keepView); }catch(e2){} } }
  }

  function drawPins(keepView){
    var pts=all.filter(function(p){
      if(PLPFILTER==='all') return true;
      var isRent = p.funnel==='rent';
      return PLPFILTER==='rent' ? isRent : !isRent;
    });
    /* на страницах каталога карта показывает ровно то, что осталось в списке */
    if(typeof window.PLP_MAP_FILTER==='function'){
      var keep=window.PLP_MAP_FILTER();
      if(keep && keep.length) pts=pts.filter(function(p){ return keep.indexOf(p.property_id)>=0; });
    }
    if(PLPLAYER){ PLPMAP.removeLayer(PLPLAYER); }
    PLPLAYER=L.layerGroup().addTo(PLPMAP);
    PLPMARKS={};

    /* Соседние объекты сливаем в одну метку со счётчиком, иначе ценники
       наезжают друг на друга. Порог зависит от масштаба: чем ближе, тем мельче
       сетка, и на зуме метки расходятся сами. */
    var z=PLPMAP.getZoom();
    var step = z>=16 ? 0.0006 : z>=15 ? 0.0015 : z>=14 ? 0.004 : z>=13 ? 0.008 : z>=12 ? 0.02 : 0.035;
    var groups={};
    pts.forEach(function(p){
      var k=Math.round(p.lat/step)+'|'+Math.round(p.lng/step);
      (groups[k]=groups[k]||[]).push(p);
    });

    var bounds=[];
    Object.keys(groups).forEach(function(k){
      var g=groups[k], p=g[0];
      /* 🔴 17.09 Эльнур: «карта — это вообще просто глюк, точки на ней улетают при зуме».
         Метка группы стояла в координатах ПЕРВОГО попавшегося её участника. Сетка склейки
         меняется на каждом шаге зума → меняется состав групп → меняется «первый», и слой
         пересобирается уже с другими опорными точками: на переходе z11→z12 прыгали 35 меток
         из 64, рекорд 4,12 км. Ставим метку в середину группы — прыжок не больше ячейки. */
      var ll = g.length > 1
        ? [g.reduce(function(a,x){return a+Number(x.lat);},0)/g.length,
           g.reduce(function(a,x){return a+Number(x.lng);},0)/g.length]
        : [Number(p.lat),Number(p.lng)];
      bounds.push(ll);
      if(g.length>1){
        var c=L.marker(ll,{icon:L.divIcon({className:'plp-icon',
          html:'<span class="plp-cluster">'+g.length+'</span>',iconSize:[0,0],iconAnchor:[0,0]})});
        c.on('click', function(){ if(PLPMAP.getZoom()<15) PLPMAP.flyTo(ll, Math.min(PLPMAP.getZoom()+3,16),{duration:.6}); });
        c.bindPopup(popupMany(g),{maxWidth:260,minWidth:236});
        c.on('mouseover', function(){ if(!('ontouchstart' in window)) this.openPopup(); });
        c.addTo(PLPLAYER);
        /* Соседей карта слепила в одну метку. Чтобы наведение на карточку в списке
           всё равно что-то подсвечивало, каждый объект группы смотрит на эту метку. */
        g.forEach(function(x){ PLPMARKS[x.property_id]=c; });
      } else {
        var isRent=p.funnel==='rent';
        var m=L.marker(ll,{icon:L.divIcon({className:'plp-icon',
          html:'<span class="plp-pin'+(isRent?' rent':'')+(p.coordOk?'':' approx')+'">'+
               fmtBaht(thbOf(p))+'</span>',
          iconSize:[0,0], iconAnchor:[0,0]})});
        m.bindPopup(popupOne(p),{maxWidth:260,minWidth:236});
        /* Эльнур 05.09: карточка объекта должна всплывать по наведению, а не только
           по клику. На телефоне наведения нет — там остаётся тап. */
        m.on('mouseover', function(){ if(!('ontouchstart' in window)) this.openPopup(); });
        m.on('mouseout', function(){
          if('ontouchstart' in window) return;
          var self=this;
          clearTimeout(self.__hideT);
          self.__hideT=setTimeout(function(){ self.closePopup(); }, 260);
        });
        m.on('popupopen', function(e){
          var self=this, el=e.popup.getElement();
          if(!el) return;
          /* курсор ушёл на саму карточку — не закрываем, дадим прочитать и нажать */
          el.addEventListener('mouseenter', function(){ clearTimeout(self.__hideT); });
          el.addEventListener('mouseleave', function(){
            clearTimeout(self.__hideT);
            self.__hideT=setTimeout(function(){ self.closePopup(); }, 260);
          });
        });
        m.addTo(PLPLAYER);
        PLPMARKS[p.property_id]=m;
      }
    });

    var note=document.getElementById('plpNote');
    if(note){
      var hidden=PL.PROPERTIES.length+PL.RENTALS.length-all.length;
      /* 21.09: подпись карты была только по-русски и оставалась такой на /en/ */
      note.textContent = (PL.lang==='en')
        ? (pts.length+' propert'+(pts.length===1?'y':'ies')+' on the map. Tap a pin to open the card.'+
           (hidden>0 ? (' Another '+hidden+' have no exact address and live in the catalogue.') : ''))
        : ('На карте '+pts.length+' объект'+plural(pts.length)+'. Нажмите метку — откроется карточка.'+
           (hidden>0 ? (' Ещё '+hidden+' — без точного адреса, они в каталоге.') : ''));
    }
    if(!keepView){
      if(bounds.length>1) PLPMAP.fitBounds(bounds,{padding:[24,24]});
      else if(bounds.length===1) PLPMAP.setView(bounds[0],14);
    }
  }

  function plural(n){ var a=n%10,b=n%100;
    return (a===1&&b!==11)?'':((a>=2&&a<=4&&(b<10||b>20))?'а':'ов'); }

  /* Своя страница есть только у продажных объектов: у арендных её намеренно нет,
     туда когда-то утекали имя собственника и номер квартиры. Для них открываем
     карточку окном, чтобы ссылка не вела в никуда. */
  function hasPage(p){
    return PL.PROPERTIES.some(function(x){ return x.property_id===p.property_id; });
  }
  function href(p){ return 'object/'+String(p.property_id||'').replace(/^PLP-/,'').toLowerCase()+'.html'; }
  function popupBody(p){
    return '<span class="t"><b>'+p.title+'</b><span>'+loc(p.loc)+' · '+p.beds+'</span>'+
      '<span class="price">'+fmtBaht(thbOf(p))+'</span>'+
      (p.coordOk?'':'<span style="font-size:11.5px;color:#8a8a80;margin-top:4px">расположение примерное — уточняем</span>')+
      '<span class="go">Открыть объект →</span></span>';
  }
  function popupOne(p){
    return hasPage(p)
      ? '<a class="plp-pop" href="'+href(p)+'">'+popupBody(p)+'</a>'
      : '<a class="plp-pop" href="#" onclick="event.preventDefault();openProp(\''+p.property_id+'\')">'+popupBody(p)+'</a>';
  }
  function popupMany(g){
    return '<span class="t" style="display:block;padding:12px 13px"><b>'+loc(g[0].loc)+
      '</b><span style="margin-bottom:6px">'+g.length+' объект'+plural(g.length)+' рядом</span>'+
      g.map(function(p){
        var open = hasPage(p) ? 'href="'+href(p)+'"'
          : 'href="#" onclick="event.preventDefault();openProp(\''+p.property_id+'\')"';
        return '<a '+open+' style="display:flex;justify-content:space-between;gap:10px;'+
          'padding:7px 0;border-top:1px solid #eeede6;color:inherit;text-decoration:none;font-size:12.5px">'+
          '<span>'+p.title+'</span><b style="white-space:nowrap">'+fmtBaht(thbOf(p))+'</b></a>';
      }).join('')+'</span>';
  }

  /* карта живёт в блоке с анимацией появления: без пересчёта размера остаётся серый прямоугольник */
  var framed=false;
  function fix(){
    try{
      PLPMAP.invalidateSize();
      /* пока блок скрыт, размер нулевой и рамка считается неверно —
         подгоняем её один раз, когда карта уже видна */
      if(!framed && box.offsetWidth>200){ framed=true; drawPins(); }
    }catch(e){}
  }
  setTimeout(fix,150); setTimeout(fix,600); setTimeout(fix,1500);
  window.addEventListener('resize',fix);
  if(window.IntersectionObserver){
    var io=new IntersectionObserver(function(en){ en.forEach(function(e){ if(e.isIntersecting) fix(); }); });
    io.observe(box);
  }
}

/* каталог просит карту перерисоваться после фильтров */
window.drawPinsExternal=function(){ try{ if(PLPMAP) renderMapReal.__draw && renderMapReal.__draw(true); }catch(e){} };
/* подсветка сразу нескольких меток: наводим на район — горят все его объекты */
window.PLP_HIGHLIGHT_MANY=function(ids){
  var want={};
  (ids||[]).forEach(function(id){
    var m=PLPMARKS[id];
    var el=m && m.getElement && m.getElement();
    if(el) want[el.__zk=(el.__zk||Math.random())]=el;
  });
  Object.keys(PLPMARKS).forEach(function(k){
    var el=PLPMARKS[k].getElement && PLPMARKS[k].getElement();
    if(el && !(el.__zk in want)) el.classList.remove('mark-hl');
  });
  Object.keys(want).forEach(function(k){ want[k].classList.add('mark-hl'); });
};
/* подсветка метки при наведении на карточку в списке */
window.PLP_HIGHLIGHT=function(pid){
  /* Слитая метка стоит сразу за нескольких объектов, поэтому сначала находим
     нужную, а гасим все остальные — иначе она сама себя и погасит. */
  var want = pid && PLPMARKS[pid] && PLPMARKS[pid].getElement && PLPMARKS[pid].getElement();
  Object.keys(PLPMARKS).forEach(function(k){
    var el=PLPMARKS[k].getElement && PLPMARKS[k].getElement();
    if(el && el!==want) el.classList.remove('mark-hl');
  });
  if(want) want.classList.add('mark-hl');
  if(pid && PLPMARKS[pid] && PLPMAP){
    var ll=PLPMARKS[pid].getLatLng();
    if(!PLPMAP.getBounds().contains(ll)) PLPMAP.panTo(ll,{animate:true,duration:.4});
  }
};

/* ===== БЛОК «РАЙОНЫ»: бюджет → где что можно купить =====
   Эльнур 05.09: «блок бестолковый, сделай что-то классное». Смысл блока —
   ответить на главный вопрос покупателя: «на мои деньги — где именно?».
   Двигаешь бюджет, районы пересчитываются: сколько вариантов, с какой цены
   начинается вход, какая доходность. Выбрал район — карта летит туда, снизу
   лента его объектов. */
var ZB={lo:0,hi:0,a:0,b:0}, ZONE_SEL=null;
/* «1 объект / 2 объекта / 5 объектов» — без этого счётчики читаются коряво */
function plural(n, one, few, many){
  var a=n%10, b=n%100;
  if(a===1 && b!==11) return one;
  if(a>=2 && a<=4 && (b<10||b>=20)) return few;
  return many;
}

function zoneList(){
  return PL.DISTRICTS.filter(function(d){ return distProps(d.ru).length; });
}
function zoneSale(nameRu){
  return PL.PROPERTIES.filter(function(p){ return p.loc&&p.loc.ru===nameRu; });
}
function zoneRent(nameRu){
  return PL.RENTALS.filter(function(p){ return !p.soon && p.loc && p.loc.ru===nameRu; });
}
function inBudget(p){
  var v=thbOf(p)/1e6;
  if(ZB.b>=ZB.hi) return v>=ZB.a-0.0001;   /* верх шкалы — «и дороже» */
  return v>=ZB.a-0.0001 && v<=ZB.b+0.0001;
}
function zonePic(nameRu){
  var all=zoneSale(nameRu).concat(zoneRent(nameRu));
  for(var i=0;i<all.length;i++){ if(all[i].photo) return all[i].photo; }
  for(var j=0;j<all.length;j++){ if(all[j].img) return all[j].img; }
  return '';
}

function buildZoneBudget(){
  var track=document.getElementById('zbudTrack'); if(!track) return;
  var vals=(PL.PROPERTIES||[]).map(thbOf).filter(function(v){return v>0;});
  if(!vals.length) return;
  ZB.lo=Math.floor(Math.min.apply(null,vals)/1e6);
  ZB.hi=Math.max(Math.ceil(Math.max.apply(null,vals)/1e6),100);
  if(ZB.hi<=ZB.lo) ZB.hi=ZB.lo+1;
  ZB.a=ZB.lo; ZB.b=ZB.hi;
  var fill=document.getElementById('zbudFill'),
      hA=document.getElementById('zbudA'), hB=document.getElementById('zbudB'),
      out=document.getElementById('zbudOut');
  function pct(v){ return (v-ZB.lo)/(ZB.hi-ZB.lo)*100; }
  function draw(){
    var x=Math.min(ZB.a,ZB.b), y=Math.max(ZB.a,ZB.b);
    ZB.a=x; ZB.b=y;
    fill.style.left=pct(x)+'%'; fill.style.right=(100-pct(y))+'%';
    hA.style.left=pct(x)+'%'; hB.style.left=pct(y)+'%';
    out.textContent=fmtBaht(x*1e6)+' — '+(y>=ZB.hi ? fmtBaht(ZB.hi*1e6)+'+' : fmtBaht(y*1e6));
  }
  var drag=null;
  function valueAt(clientX){
    var r=track.getBoundingClientRect(); if(!r.width) return ZB.a;
    var k=(clientX-r.left)/r.width;
    return Math.round(ZB.lo + Math.max(0,Math.min(1,k))*(ZB.hi-ZB.lo));
  }
  function move(e){
    if(!drag) return;
    var v=valueAt(e.clientX);
    if(drag==='a') ZB.a=v; else ZB.b=v;
    draw(); renderZones();
  }
  track.addEventListener('pointerdown',function(e){
    var v=valueAt(e.clientX);
    drag=(Math.abs(v-ZB.a)===Math.abs(v-ZB.b)) ? (v<ZB.a?'a':'b')
                                               : (Math.abs(v-ZB.a)<Math.abs(v-ZB.b)?'a':'b');
    move(e);
    try{ track.setPointerCapture(e.pointerId); }catch(err){}
    e.preventDefault();
  });
  track.addEventListener('pointermove',move);
  ['pointerup','pointercancel'].forEach(function(ev){
    track.addEventListener(ev,function(e){
      drag=null; try{ track.releasePointerCapture(e.pointerId); }catch(err){}
    });
  });
  [[hA,'a'],[hB,'b']].forEach(function(pair){
    pair[0].addEventListener('keydown',function(e){
      var d=(e.key==='ArrowRight'||e.key==='ArrowUp')?1:(e.key==='ArrowLeft'||e.key==='ArrowDown')?-1:0;
      if(!d) return; e.preventDefault();
      if(pair[1]==='a') ZB.a=Math.max(ZB.lo,Math.min(ZB.hi,ZB.a+d));
      else ZB.b=Math.max(ZB.lo,Math.min(ZB.hi,ZB.b+d));
      draw(); renderZones();
    });
  });
  window.syncZoneBudget=draw;
  draw();
}

function renderZones(){
  var host=document.getElementById('zones'); if(!host) return;
  var x=document.getElementById('zpickX');
  if(x && !x.__wired){ x.__wired=1; x.onclick=function(){ zoneOpen(ZONE_SEL); }; }
  var zones=zoneList().map(function(d){
    var sale=zoneSale(d.ru), rent=zoneRent(d.ru);
    var fit=sale.filter(inBudget);
    var prices=sale.map(thbOf).filter(function(v){return v>0;});
    return { d:d, sale:sale, rent:rent, fit:fit,
             from: prices.length?Math.min.apply(null,prices):null };
  });
  /* сначала районы, где в бюджете есть что смотреть */
  zones.sort(function(a,b){
    if(!!b.fit.length - !!a.fit.length) return (b.fit.length?1:0)-(a.fit.length?1:0);
    if(b.fit.length!==a.fit.length) return b.fit.length-a.fit.length;
    return (a.from||1e12)-(b.from||1e12);
  });
  var totalFit=zones.reduce(function(n,z){return n+z.fit.length;},0);
  var zonesFit=zones.filter(function(z){return z.fit.length;}).length;
  var note=document.getElementById('zbudNote');
  if(note) note.textContent = totalFit
    /* 17.09: на одном экране три числа — 64 на карте, 53 в продаже и это.
       Здесь считается только то, что попало в выбранный бюджет: так и пишем. */
    ? (PL.lang==='en'
        ? (totalFit+' propert'+(totalFit===1?'y':'ies')+' in budget, '+
           zonesFit+' area'+(zonesFit===1?'':'s'))
        : (totalFit+' '+plural(totalFit,'объект','объекта','объектов')+' в бюджете, '+
           zonesFit+' '+plural(zonesFit,'район','района','районов')))
    : (PL.lang==='en'
        ? 'nothing fits this budget — widen the range'
        : 'в этом бюджете вариантов нет — расширьте рамки');

  host.innerHTML=zones.map(function(z){
    var pic=zonePic(z.d.ru);
    var on=(ZONE_SEL===z.d.ru);
    return '<div class="zwrap'+(on?' open':'')+'" data-zw="'+escHTML(z.d.ru)+'">'+
      '<button type="button" class="zone'+(z.fit.length?'':' dim')+(on?' on':'')+'" data-z="'+
      escHTML(z.d.ru)+'">'+
      (pic?('<i style="background-image:url('+pic+')"></i>'):'<i></i>')+
      '<span class="z-b">'+
        '<b>'+escHTML(dName(z.d))+'</b>'+
        '<u>'+(z.fit.length
                ? (PL.lang==='en'
                    ? (z.fit.length+' propert'+(z.fit.length===1?'y':'ies')+' in budget')
                    : (z.fit.length+' '+plural(z.fit.length,'объект','объекта','объектов')+' в бюджете'))
                : (z.sale.length?'вне бюджета':'только аренда'))+'</u>'+
        '<em>'+(z.from?(t('u.from')+' '+fmtBaht(z.from)):'по запросу')+'</em>'+
      '</span>'+
      '<span class="z-m">'+
        (z.d.yield?('<span class="z-y">'+escHTML(z.d.yield)+'</span>'):'')+
        '<span class="z-be">'+escHTML(loc(z.d.beach))+(PL.lang==='en'?' to the beach':' до пляжа')+'</span>'+
        (z.rent.length?('<span class="z-r">аренда: '+z.rent.length+'</span>'):'')+
        '<span class="z-chev">'+(on?'▴':'▾')+'</span>'+
      '</span></button>'+
      '<div class="zbody">'+(on?zoneBodyHTML(z.d.ru):'')+'</div>'+
      '</div>';
  }).join('');

  Array.prototype.forEach.call(host.querySelectorAll('.zone'),function(el){
    var name=el.dataset.z;
    el.addEventListener('mouseenter',function(){ zoneHover(name); });
    el.addEventListener('click',function(){ zoneOpen(name); });
  });
}

/* наведение на район — подсвечиваем его объекты на карте */
function zoneHover(nameRu){
  var ids=zoneSale(nameRu).concat(zoneRent(nameRu)).map(function(p){return p.property_id;});
  if(window.PLP_HIGHLIGHT_MANY) window.PLP_HIGHLIGHT_MANY(ids);
}

/* содержимое раскрытой карточки района: его объекты лентой */
function zoneBodyHTML(nameRu){
  var sale=zoneSale(nameRu), rent=zoneRent(nameRu);
  var fit=sale.filter(inBudget), rest=sale.filter(function(p){return fit.indexOf(p)<0;});
  var list=fit.concat(rest, rent);
  var d=null; PL.DISTRICTS.forEach(function(x){ if(x.ru===nameRu) d=x; });
  var meta=[(d&&d.yield)?('доходность '+d.yield):'', (d?loc(d.who):'')].filter(Boolean).join(' · ');
  return (meta?('<p class="zmeta">'+escHTML(meta)+'</p>'):'')+
    '<div class="car zpick-car">'+list.map(function(p){
      var pic=p.photo||p.img||'';
      var out=(p.funnel==='sale' && fit.indexOf(p)<0);
      return '<button type="button" class="zprop'+(out?' out':'')+'" data-pid="'+p.property_id+'">'+
        '<i style="'+(pic?('background-image:url('+pic+')'):'')+'"></i>'+
        '<b>'+escHTML(p.title)+'</b>'+
        '<u>'+escHTML(loc(p.type))+(p.beds?(' · '+escHTML(p.beds)+' сп.'):'')+'</u>'+
        '<em>'+(p.funnel==='sale'?(t('u.from')+' '+fmtBaht(thbOf(p))):rentPriceShort(p))+'</em>'+
        (out?'<s>вне бюджета</s>':'')+'</button>';
    }).join('')+'</div>';
}
function zoneOpen(nameRu){
  ZONE_SEL=(ZONE_SEL===nameRu)?null:nameRu;
  renderZones();
  if(!ZONE_SEL){ resetMapView(); return; }
  /* объекты района открылись прямо в карточке — вешаем на них действия */
  var wrap=document.querySelector('.zwrap[data-zw="'+nameRu.replace(/"/g,'')+'"]');
  var car=wrap&&wrap.querySelector('.zpick-car');
  if(car){
    Array.prototype.forEach.call(car.querySelectorAll('.zprop'),function(el){
      el.addEventListener('click',function(e){ e.stopPropagation(); openProp(el.dataset.pid); });
      el.addEventListener('mouseenter',function(){
        if(window.PLP_HIGHLIGHT) window.PLP_HIGHLIGHT(el.dataset.pid);
      });
    });
  }
  focusDistrict(nameRu);
  try{ initCarHint(); }catch(e){}
}

/* Список объектов рядом с картой: наводишь — метка загорается, нажимаешь —
   открывается карточка. Работает вместе с фильтрами «Все / Продажа / Аренда». */
function renderMapObjs(filter){
  var host=document.getElementById('mapObjs'); if(!host) return;
  var f=filter||(window.__mapFilter||'all');
  var list=[].concat(PL.PROPERTIES, PL.RENTALS).filter(function(p){
    if(!p.lat||!p.lng||p.soon) return false;
    if(f==='sale') return p.funnel==='sale';
    if(f==='rent') return p.funnel==='rent';
    return true;
  });
  var cnt=document.getElementById('mapCount');
  if(cnt) cnt.textContent=list.length;
  host.innerHTML=list.map(function(p){
    var pic=p.photo||p.img||'';
    return '<button type="button" class="mobj" data-pid="'+p.property_id+'">'+
      (pic?('<i style="background-image:url('+pic+')"></i>'):'<i class="nopic"></i>')+
      '<span><b>'+escHTML(p.title)+'</b>'+
      '<u>'+escHTML(loc(p.loc))+' · '+escHTML(loc(p.type))+(p.beds?(' · '+escHTML(p.beds)+' сп.'):'')+'</u>'+
      '<em>'+(p.funnel==='sale'?(t('u.from')+' '+fmtBaht(thbOf(p))):rentPriceShort(p))+'</em>'+
      '</span></button>';
  }).join('');
  Array.prototype.forEach.call(host.querySelectorAll('.mobj'),function(el){
    var pid=el.dataset.pid;
    el.addEventListener('mouseenter',function(){
      if(window.PLP_HIGHLIGHT) window.PLP_HIGHLIGHT(pid);
      Array.prototype.forEach.call(host.children,function(x){ x.classList.toggle('on', x===el); });
    });
    el.addEventListener('click',function(){ openProp(pid); });
  });
}
function renderDList(){
  var list=document.getElementById('dList');if(!list)return;
  list.innerHTML=PL.DISTRICTS.map(function(d,i){
    var n=distProps(d.ru).length;
    /* доходность есть не у всех районов: где своих замеров нет, строку не рисуем */
    var tail = n ? (n+t('d.inbase')+(d.yield||'')) : (d.yield||'');
    /* Миниатюра района — берём снимок объекта, который в нём стоит. Так список
       перестаёт быть просто текстом. Эльнур 05.09. */
    var pics=distProps(d.ru).map(function(x){ return x.photo||x.img; }).filter(Boolean);
    var thumb=pics.length?('<i class="dpic" style="background-image:url('+pics[0]+')"></i>'):'';
    var inner=thumb+'<span class="dtxt"><b>'+dName(d)+'</b><span>'+loc(d.vibe)+'</span>'+
              (tail?('<u>'+tail+'</u>'):'')+'</span>';
    return '<button type="button" class="dcard'+(thumb?' has-pic':'')+'" data-d="'+i+'">'+inner+'</button>';
  }).join('');
  list.querySelectorAll('button.dcard').forEach(function(el){
    el.addEventListener('click',function(){
      var d=PL.DISTRICTS[+el.dataset.d];
      /* подсвечиваем выбранный, ведём карту к району и открываем окно —
         так человек не уходит со страницы и не теряет место */
      list.querySelectorAll('.dcard').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on');
      /* карту не двигаем, пока открыто окно: Leaflet теряет размер под модалом,
         и первый клик получался дёрганым. Карта поедет по кнопке «Показать на карте». */
      openDistrict(d.ru);
    });
  });
}
/* карта приближается к району: по объектам, если они есть, иначе по центру района */
function focusDistrict(nameRu){
  if(!PLPMAP) return;
  var d=null; PL.DISTRICTS.forEach(function(x){ if(x.ru===nameRu) d=x; });
  var pts=distProps(nameRu).filter(function(p){return p.lat&&p.lng;})
    .map(function(p){return [Number(p.lat),Number(p.lng)];});
  try{
    if(pts.length>1) PLPMAP.flyToBounds(pts,{padding:[60,60],maxZoom:14,duration:.8});
    else if(pts.length===1) PLPMAP.flyTo(pts[0],14,{duration:.8});
    else if(d) PLPMAP.flyTo([d.lat,d.lng],13,{duration:.8});
  }catch(e){}
}
/* вернуть общий вид острова */
function resetMapView(){
  if(!PLPMAP) return;
  var all=PL.PROPERTIES.concat(PL.RENTALS).filter(function(p){return p.lat&&p.lng;})
    .map(function(p){return [Number(p.lat),Number(p.lng)];});
  var list=document.getElementById('dList');
  if(list) list.querySelectorAll('.dcard').forEach(function(x){x.classList.remove('on');});
  try{ if(all.length>1) PLPMAP.flyToBounds(all,{padding:[24,24],duration:.7}); }catch(e){}
}

function openDistrict(nameRu){
  var d=null;
  PL.DISTRICTS.forEach(function(x){if(x.ru===nameRu)d=x;});
  if(!d)return;
  var items=distProps(nameRu);
  document.getElementById('dTitle').textContent=dName(d);
  document.getElementById('dBody').innerHTML=
    '<div class="dfacts">'+(d.yield?('<div><b>'+d.yield+'</b><span>'+t('d.yield')+'</span></div>'):'')+
    '<div><b>'+loc(d.beach)+'</b><span>'+t('d.beach')+'</span></div>'+
    '<div><b>'+items.length+'</b><span>'+t('d.count')+'</span></div></div>'+
    '<p style="font-size:.9rem;line-height:1.6;color:var(--muted);margin:0">'+loc(d.vibe)+'. '+t('d.who')+loc(d.who).toLowerCase()+'.</p>'+
    (items.length?('<div class="dprops">'+items.map(function(p){
      return '<button type="button" data-pid="'+p.property_id+'">'+thumbDiv(p)+'<b>'+p.title+'</b><span>'+(p.funnel==='sale'?fmtBaht(thbOf(p)):rentPriceShort(p))+'</span></button>';
    }).join('')+'</div>'):('<p style="font-size:.84rem;color:var(--muted);margin:14px 0 0">'+t('d.none')+'</p>'));
  document.getElementById('dBody').querySelectorAll('.dprops button').forEach(function(b){
    b.addEventListener('click',function(){closeDistrict();openProp(b.dataset.pid);});
  });
  /* под содержимым — что делать дальше: остаться на карте или уйти в подробную страницу */
  var slug=DPAGE[nameRu], extra=document.getElementById('dExtra');
  if(extra){
    extra.innerHTML='<button type="button" class="btn btn-ghost" id="dMap">Показать на карте</button>'+
      (slug?'<a class="btn btn-ghost" href="/districts/'+slug+'">Подробно о районе</a>':'');
    var bm=document.getElementById('dMap');
    if(bm) bm.onclick=function(){
      closeDistrict(); focusDistrict(nameRu);
      var box=document.getElementById('plpMap');
      if(box) window.scrollTo({top:box.getBoundingClientRect().top+window.scrollY-90,behavior:'smooth'});
    };
  }
  var cta=document.getElementById('dCta');
  cta.textContent=t('d.cta')+dName(d);
  cta.onclick=function(){closeDistrict();pushLead({funnel:'sale',goal:'district',note:nameRu});openChat('district');setTimeout(function(){offerLead(true);},600);};
  document.getElementById('distModal').classList.add('open');document.body.style.overflow='hidden';
}
function closeDistrict(){document.getElementById('distModal').classList.remove('open');document.body.style.overflow='';
  /* пока окно было открыто, страница не прокручивалась — карта могла потерять размер */
  setTimeout(function(){ try{ if(PLPMAP) PLPMAP.invalidateSize(); }catch(e){} },80);}

